    for name in ("MainMenuBarTexture0", "MainMenuXPBarTexture0", "MainMenuMaxLevelBar0",
                "MainMenuBarLeftEndCap", "MainMenuBarRightEndCap", "MainMenuBarExpText"):
        assert g[name].alpha == 0, "%s reste visible sous la nouvelle barre" % name
    print("anciens morceaux effaces : corps, barre d'xp, version niveau max, embouts, texte")
    print("fleches de page habillees : %s" % (g.ActionBarUpButton.foreverSkinned == True))
    page = g.ForeverUIActionBarPage
    ph = page.points[1]
    ph_top = g.ActionBarUpButton.points[1]
    print("bloc de pagination : %d x %d, %s sur %s (%s, %s) | fleche haut centree a y=%s" % (
        page.width, page.height, ph[1], ph[3], ph[4], ph[5], ph_top[5]))
    assert page.width == 17 and page.height == 34
    assert ph[4] == -4 and ph[5] == 9, "le bloc de pagination n est pas a gauche de la barre"
    assert ph_top[5] == 10 and g.ActionBarDownButton.points[1][5] == -10
    # The bonus bar (which replaces the action bar on a stance change) takes exactly
    # the same place, so it follows the position the player chose for the holder.
    main = g.ActionButton3.points[len(list(g.ActionButton3.points.values()))]
    bonus = g.BonusActionButton3.points[len(list(g.BonusActionButton3.points.values()))]
    print("barre bonus : bouton 3 en %s (%s, %s) | barre de sorts en %s (%s, %s)" % (
        bonus[1], bonus[4], bonus[5], main[1], main[4], main[5]))
    assert (bonus[1], bonus[4], bonus[5]) == (main[1], main[4], main[5]),         "la barre bonus doit se poser exactement sur la barre de sorts"
    assert main[2].name == "ForeverUIActionBarHolder",         "la barre de sorts s ancre au porteur"
    assert bonus[2].name == "ForeverUIBonusSlide",         "la barre bonus s ancre a la glissiere, qui est posee sur le porteur"
    assert g.BonusActionButton1.width == 45, "ses boutons ont la taille des autres"
    # Slide-in. The slide frame is ours: moving it is allowed in combat, moving a
    # secure button is not.
    track = g.ForeverUI.ActionBarSlide
    g.BonusActionBarFrame.Hide(g.BonusActionBarFrame)
    track.scripts.OnUpdate(track, 0.05)
    g.BonusActionBarFrame.Show(g.BonusActionBarFrame)
    track.scripts.OnUpdate(track, 0.0)
    origin = track.points[1][5]
    print("   glissement : depart a %.0f (une hauteur de bouton sous le porteur)" % origin)
    assert origin == -45, "la barre doit partir d une hauteur de bouton plus bas"
    track.scripts.OnUpdate(track, 0.1)
    middle = track.points[1][5]
    track.scripts.OnUpdate(track, 0.2)
    finish = track.points[1][5]
    print("   a mi-course %.1f, puis %.1f (au repos sur le porteur)" % (middle, finish))
    assert origin < middle < finish, "elle doit remonter progressivement"
    assert finish == 0, "elle doit finir exactement sur le porteur"
    # and it stays still while the bar remains shown
    track.scripts.OnUpdate(track, 0.5)
    assert track.points[1][5] == 0, "au repos, la glissiere ne bouge plus"

    # Slide-out. The client sets mode = "hide", keeps the bar shown during the motion,
    # then hides it: the slide frame goes back down.
    lua.execute('BonusActionBarFrame.mode = "hide"')
    track.scripts.OnUpdate(track, 0.1)
    descent = track.points[1][5]
    print("   retrait : a mi-course %.1f" % descent)
    assert -45 < descent < 0, "elle doit redescendre progressivement"
    track.scripts.OnUpdate(track, 0.2)
    print("   puis %.0f (sortie)" % track.points[1][5])
    assert track.points[1][5] == -45, "elle doit finir une hauteur de bouton plus bas"

    # the client finally hides it: it is ready to slide up again
    lua.execute('BonusActionBarFrame.mode = "none"')
    g.BonusActionBarFrame.Hide(g.BonusActionBarFrame)
    track.scripts.OnUpdate(track, 0.05)
    g.BonusActionBarFrame.Show(g.BonusActionBarFrame)
    track.scripts.OnUpdate(track, 0.0)
    print("   a la posture suivante : depart a %.0f" % track.points[1][5])
    assert track.points[1][5] == -45, "le mouvement suivant repart d en bas"

    print("   art d'epoque de la barre bonus : %s et %s" % (
        g.BonusActionBarTexture0.alpha, g.BonusActionBarTexture1.alpha))
    assert g.BonusActionBarTexture0.alpha == 0 and g.BonusActionBarTexture1.alpha == 0,         "l art glissant d epoque doit disparaitre"

    # Moving the holder: the bonus bar follows since it is anchored to it. Then
    # restore the exact previous values: the bottom row recomputes them at load,
    # so they differ from those given to Register.
    before = g.ForeverUI.Layout.systems["actionbar"].defaults
    keep = (before.point, before.relativePoint, before.x, before.y)
    g.ForeverUI.Layout.SetDefaults("actionbar", "BOTTOMRIGHT", "BOTTOM", -100, 200)
    g.HOOKS["ActionButton_Update"](g.ActionButton1)
    after = g.BonusActionButton3.points[len(list(g.BonusActionButton3.points.values()))]
    print("   porteur deplace : la barre bonus reste ancree a lui (%s)" % after[1])
    assert after[2].name == "ForeverUIBonusSlide",         "elle doit rester ancree a la glissiere, pas a l ecran"
    g.ForeverUI.Layout.SetDefaults("actionbar", keep[0], keep[1], keep[2], keep[3])

    print("ancien fond du client efface : %s | porteur enregistre : %s" % (
        g["MainMenuBarTexture0"].alpha == 0,
        g.ForeverUI.Layout.systems["actionbar"] is not None))

    # ------------------------------------------------ stance bar
    carrier = g.ForeverUIStanceBarHolder
    b1 = g.ShapeshiftButton1
    print("posture : bouton %d x %d (SmallActionButtonTemplate : 30)" % (b1.width, b1.height))
    assert b1.width == 30 and b1.height == 30, "le bouton de posture fait 30"

    p2 = g.ShapeshiftButton2.points[len(list(g.ShapeshiftButton2.points.values()))]
    print("   pas entre boutons : %d (32 attendu : 30 + minButtonPadding 2)" % p2[4])
    assert p2[4] == 32, "le pas n est pas 30 + 2"

    print("   porteur : %d x %d pour %d formes, visible=%s" % (
        carrier.width, carrier.height, g.GetNumShapeshiftForms(), carrier.shown))
    assert carrier.width == 3 * 30 + 2 * 2, "la barre ne fait pas la largeur de ses formes"
    assert carrier.shown, "la barre doit se montrer des qu il y a une forme"

    frame = b1.foreverFrame
    pc = frame.points[1]
    print("   cadre : %s %.1f x %.1f en %s, ancre %s (centre sur le bouton)" % (
        frame.texture and "pose" or "absent", frame.width, frame.height, frame.layer, pc[1]))
    assert frame.width == 35 and frame.height == 35, "UpdateButtonArt ramene le petit cadre a 35"
    assert frame.layer == "OVERLAY" and pc[1] == "CENTER",         "un cadre de 35 sur un bouton de 30 doit etre centre, pas ancre TOPLEFT"
    assert b1._normal.alpha == 0, "la texture normale du client doit rester muette"

    hover, checkMark = b1._highlight, b1._checked
    print("   survol %.1f x %.1f en %s | coche %.1f x %.1f en %s" % (
        hover.width, hover.height, hover.blend,
        checkMark.width, checkMark.height, checkMark.blend))
    for region, name in ((hover, "hover"), (checkMark, "checkMark")):
        assert abs(region.width - 31.6) < 0.01 and abs(region.height - 30.9) < 0.01, \
            "SmallActionButtonMixin pose %s en 31,6 x 30,9" % name
    assert checkMark.blend == "ADD", "le coche est le survol en melange ADD"
    assert hover.blend == "BLEND"

    print("   emplacement vide : fond=%s + art=%s" % (
        b1.foreverBackground is not None, b1.foreverSlot is not None))
    assert b1.foreverBackground is not None and b1.foreverSlot is not None

    hotkey = g["ShapeshiftButton1HotKey"].points[1]
    quantity = g["ShapeshiftButton1Count"].points[1]
    print("   raccourci %s (%s, %s) | quantite %s (%s, %s)" % (
        hotkey[1], hotkey[4], hotkey[5], quantity[1], quantity[4], quantity[5]))
    assert (hotkey[1], hotkey[4], hotkey[5]) == ("TOPRIGHT", -3, -4)
    assert (quantity[1], quantity[4], quantity[5]) == ("BOTTOMRIGHT", -3, 1)

    cooldown = g["ShapeshiftButton1Cooldown"]
    r1, r2 = cooldown.points[1], cooldown.points[2]
    print("   recharge : %s (%s, %s) et %s (%s, %s)" % (
        r1[1], r1[4], r1[5], r2[1], r2[4], r2[5]))
    assert (r1[4], r1[5]) == (1.7, -1.7) and (r2[4], r2[5]) == (-1, 1), \
        "la recharge n est pas en retrait de l icone comme dans la source"

    # 3.3.5 signature: GetShapeshiftFormInfo returns (texture, name, isActive,
    # isCastable); reading the source literally would take the name for the active state.
    i1 = g.ShapeshiftButton1.foreverIcon
    i2 = g.ShapeshiftButton2.foreverIcon
    i3 = g.ShapeshiftButton3.foreverIcon
    print("   formes : 1 cochee=%s | 2 cochee=%s (active) | 3 teinte %s (non lancable)" % (
        g.ShapeshiftButton1.checked, g.ShapeshiftButton2.checked,
        [round(v, 2) for v in i3.vertex.values()] if i3.vertex else None))
    assert i1.texture == "forme_ours", "l icone ne prend pas la texture de la forme"
    assert not g.ShapeshiftButton1.checked and g.ShapeshiftButton2.checked, \
        "c est la forme ACTIVE qui est cochee"
    assert [round(v, 2) for v in i3.vertex.values()] == [0.4, 0.4, 0.4], \
        "une forme non lancable est grisee a 0,4"
    assert [round(v, 2) for v in i2.vertex.values()] == [1, 1, 1], \
        "une forme lancable reste blanche"

    # Without forms, the bar hides (StanceBarMixin:ShouldShow).
    lua.execute("FORMES_GARDEES = SHAPESHIFT_FORMS; SHAPESHIFT_FORMS = {}")
    g.ForeverUI.StanceBar.Apply()
    print("   sans aucune forme : visible=%s (masquee attendue)" % carrier.shown)
    assert not carrier.shown, "la barre doit disparaitre quand il n y a aucune forme"
    lua.execute("SHAPESHIFT_FORMS = FORMES_GARDEES")
    g.ForeverUI.StanceBar.Apply()
    assert carrier.shown

    # In combat nothing changes: secure frames.
    g.STATE.inLockdown = True
    width = carrier.width
    lua.execute("table.insert(SHAPESHIFT_FORMS, { texture = 'x', name = 'x', active = false, castable = true })")
    g.ForeverUI.StanceBar.Apply()
    print("   une forme de plus en combat : largeur %d (inchangee)" % carrier.width)
    assert carrier.width == width, "rien ne doit bouger en combat"
    g.STATE.inLockdown = False
    g.ForeverUI.StanceBar.Apply()
    print("   apres le combat : largeur %d pour 4 formes" % carrier.width)
    assert carrier.width == 4 * 30 + 3 * 2, "la barre doit se refaire a la sortie du combat"
    lua.execute("table.remove(SHAPESHIFT_FORMS)")
    g.ForeverUI.StanceBar.Apply()

    print("   ancien art efface : %s | porteur enregistre : %s" % (
        g.ShapeshiftBarLeft.alpha == 0,
        g.ForeverUI.Layout.systems["stances"] is not None))
    assert g.ShapeshiftBarLeft.alpha == 0, "l art d epoque de la barre doit s effacer"

    # -------------------------------------------- pet bar
    pet = g.ForeverUIPetBarHolder
    p1 = g.PetActionButton1
    print("familier : bouton %d x %d, porteur %d x %d, visible=%s" % (
        p1.width, p1.height, pet.width, pet.height, pet.shown))
    assert p1.width == 30 and p1.height == 30, "le bouton du familier fait 30"
    assert pet.width == 10 * 30 + 9 * 2, "dix emplacements au pas de 32"
    assert pet.shown, "la barre se montre quand le familier a la sienne"

    pp = g.PetActionButton2.points[len(list(g.PetActionButton2.points.values()))]
    assert pp[4] == 32, "le pas n est pas 30 + 2"

    frame = p1.foreverFrame
    print("   cadre %.1f x %.1f en %s ancre %s | survol %.1f x %.1f | coche en %s" % (
        frame.width, frame.height, frame.layer, frame.points[1][1],
        p1._highlight.width, p1._highlight.height, p1._checked.blend))
    assert frame.width == 35 and frame.points[1][1] == "CENTER"
    assert abs(p1._highlight.width - 31.6) < 0.01 and p1._checked.blend == "ADD"

    # UpdateButtonState: attack is active and checked, and its check alpha drops to
    # 0.5, as the source states.
    print("   attaque : cochee=%s, alpha du coche %.2f (0,5 attendu)" % (
        p1.checked, p1._checked.alpha))
    assert p1.checked, "l action active doit etre cochee"
    assert abs(p1._checked.alpha - 0.5) < 0.01, "le coche de l attaque est a 0,5"

    # 3.3.5 signature: (name, subtext, texture, ...). Reading the subtext as the
    # texture would give a rank 5 icon the path "Rank 5".
    i2 = g.PetActionButton2.foreverIcon
    print("   icone 2 : %s (la texture, pas le sous-texte)" % i2.texture)
    assert i2.texture == "icone_morsure", "le sous-texte a ete pris pour la texture"

    # isToken: name and texture are keys of global variables.
    i3 = g.PetActionButton3.foreverIcon
    print("   icone 3 : %s (isToken : la cle est resolue)" % i3.texture)
    assert i3.texture == "icone_passif_resolue", "une cle de token doit etre resolue"
    assert [round(v, 2) for v in i3.vertex.values()] == [0.4, 0.4, 0.4], \
        "une action inutilisable est grisee a 0,4"

    # Autocast stays the client's. AutoCastTemplates only exists in mainline/, and
    # only camelot/ and shared/ are authoritative: camelot keeps its own shimmering
    # border and sparkles here. We only scale them to the button, 30 instead of 36.
    border = g["PetActionButton1AutoCastable"]
    sparkles = g["PetActionButton1Shine"]
    print("   autolancement du client : bordure %.1f (58 x 30/36) | etincelles a l echelle %.3f" % (
        border.width, sparkles.GetScale(sparkles)))
    assert abs(border.width - 58 * 30 / 36.0) < 0.01,         "la bordure d origine doit suivre l echelle du bouton"
    assert abs(sparkles.GetScale(sparkles) - 30 / 36.0) < 0.001,         "les etincelles se mettent a l echelle, elles ne se redimensionnent pas"
    assert border.alpha != 0, "la bordure du client ne doit plus etre effacee"
    assert g.PetActionButton1.foreverRing is None,         "l anneau maison est retire : camelot garde ici le comportement d origine"

    # without a pet, the bar hides
    lua.execute("PET_HAS_BAR = false")
    g.ForeverUI.PetBar.Apply()
    print("   sans familier : visible=%s (masquee attendue)" % pet.shown)
    assert not pet.shown, "la barre doit disparaitre sans familier"
    lua.execute("PET_HAS_BAR = true")
    g.ForeverUI.PetBar.Apply()
    assert pet.shown
    assert g.ForeverUI.Layout.systems["pet"] is not None

    # Position: just above the reputation bar, right of the stance bar when shown,
    # two icons away from it.
    stances = g.ForeverUIStanceBarHolder
    pp = pet.points[len(list(pet.points.values()))]
    expected = -587.5 + stances.width + 2 * 30
    print("   place : %s (%.1f, %.1f) | postures larges de %d -> %.1f attendu" % (
        pp[1], pp[4], pp[5], stances.width, expected))
    assert pp[5] == 84, "la barre doit etre juste au-dessus de la reputation"
    assert abs(pp[4] - expected) < 0.01, "elle doit se decaler de deux icones apres les postures"

    # without stances, it goes back to the left edge
    lua.execute("FORMES_2 = SHAPESHIFT_FORMS; SHAPESHIFT_FORMS = {}")
    g.ForeverUI.StanceBar.Apply()
    g.ForeverUI.PetBar.Apply()
    pp = pet.points[len(list(pet.points.values()))]
    print("   sans posture : x=%.1f (-587,5 attendu)" % pp[4])
    assert abs(pp[4] + 587.5) < 0.01, "sans postures elle reprend le bord gauche"
    lua.execute("SHAPESHIFT_FORMS = FORMES_2")
    g.ForeverUI.StanceBar.Apply()
    g.ForeverUI.PetBar.Apply()

    # The bar's legacy art is cleared by sweeping the frame's regions rather than
    # relying on names.
    print("   art d'epoque : morceau 0 alpha=%s, morceau 1 alpha=%s" % (
        g.SlidingActionBarTexture0.alpha, g.SlidingActionBarTexture1.alpha))
    assert g.SlidingActionBarTexture0.alpha == 0 and g.SlidingActionBarTexture1.alpha == 0,         "l art d epoque de la barre du familier doit disparaitre"
    # The bonus bar takes no mouse input. It is declared 505 x 43, HIGH strata,
    # toplevel and enableMouse: clearing its art makes it invisible but not harmless,
    # it would swallow the micro menu clicks.
    print("   barre bonus : souris=%s, art efface=%s" % (
        g.BonusActionBarFrame.mouseEnabled,
        all(r.alpha == 0 for r in g.BonusActionBarFrame.regions.values())))
    assert g.BonusActionBarFrame.mouseEnabled is False,         "un cadre qui ne sert que de contenant n a pas a recevoir de clic"
    assert g.MainMenuBar.mouseEnabled is False,         "MainMenuBar couvre tout le bas de l ecran : elle non plus"

    # The client moves the micro buttons back: VehicleMenuBar_MoveMicroButtons
    # re-anchors the first one and the social one on every vehicle enter or exit,
    # so we re-place them after it.
    g.CharacterMicroButton.SetPoint(g.CharacterMicroButton, "BOTTOMLEFT", 552, 2)
    g.VehicleMenuBar_MoveMicroButtons()
    pc = g.CharacterMicroButton.points[len(list(g.CharacterMicroButton.points.values()))]
    print("   apres le vehicule : %s sur %s (%s, %s)" % (
        pc[1], pc[2].name if pc[2] else None, pc[4], pc[5]))
    assert pc[2] and pc[2].name == "ForeverUIMicroMenu",         "le bouton revient sur notre bandeau"
    assert (pc[1], pc[4], pc[5]) == ("LEFT", 0, 0), "et a sa place"

    lateTexture = g.PetActionBarFrame.CreateTexture(g.PetActionBarFrame, None, "ARTWORK")
    g.ForeverUI.PetBar.Apply()
    print("   une texture ajoutee apres coup : alpha=%s" % lateTexture.alpha)
    assert lateTexture.alpha == 0, "le balayage doit aussi prendre ce qui arrive ensuite"

    # ---------------------------------------- character sheet
    character = g.CharacterFrame
    left = g.ForeverUICharacterLeftPane
    right = g.ForeverUICharacterRightPane
    print("feuille du personnage : %d x %d (631 x 484 attendu)" % (character.width, character.height))
    assert character.width == 631 and character.height == 484, "CHARACTER_FRAME_WIDTH et _HEIGHT"
    print("   volets : gauche %d, droit %d (398 + 233 = %d)" % (
        left.width, right.width, left.width + right.width))
    assert left.width == 398 and right.width == 233
    assert left.width + right.width == character.width, "les deux volets font la fenetre"
    pg = left.points[1]
    assert (pg[1], pg[4], pg[5]) == ("TOPLEFT", 0, -20), "le volet gauche part 20 sous le haut"
    pd = right.points[1]
    assert pd[1] == "TOPLEFT" and pd[3] == "TOPRIGHT", \
        "le volet droit s accroche a la droite du gauche"
    assert g.CharacterFrameTopLeft.alpha == 0, "l art d epoque doit disparaitre"
    assert g.PaperDollFrameTexture.alpha == 0,         "l art d epoque des sous-cadres aussi : ce sont des cadres fils"

    # The panel art draws above the panes. Panes are child frames and cover every
    # region of their parent, so the art lives in a higher-level child frame, like
    # the source's NineSlice.
    skinLayer = character.foreverSkinLayer
    print("   habillage : cadre fils de niveau +%d (volets a +%d)" % (
        skinLayer.GetFrameLevel(skinLayer) - character.GetFrameLevel(character),
        left.GetFrameLevel(left) - character.GetFrameLevel(character)))
    assert skinLayer is not None, "l art doit vivre dans son propre cadre fils"
    assert skinLayer.GetFrameLevel(skinLayer) > left.GetFrameLevel(left),         "l art doit passer au-dessus des volets"
    assert character.foreverPanel.topLeftCornerAtlas == "ui-frame-portraitmetal-cornertopleft",         "PortraitFrameTemplate prend le grand anneau, pas celui des sacs"

    # Border: camelot adjusts its layouts after defining them. Without that step the
    # bottom corners sit 5 px too high and the border stops short of the bottom.
    for key, expected in (("topLeftCorner", (-18.5, 17)), ("topRightCorner", (8.5, 17)),
                         ("bottomLeftCorner", (-18.5, -13)), ("bottomRightCorner", (8.5, -13))):
        pc = character.foreverPanel[key].points[1]
        print("   %-15s (%s, %s)" % (key, pc[4], pc[5]))
        assert (pc[4], pc[5]) == expected,             "%s : mesure du filet interieur sur l art, plus 1 px de montee" % key

    # The bags window keeps its own offsets.
    pb = g.ContainerFrame1.foreverPanel.bottomLeftCorner.points[1]
    print("   sacs, coin bas gauche : (%s, %s) -- inchange" % (pb[4], pb[5]))
    assert (pb[4], pb[5]) == (-13, -3), "la fenetre des sacs est validee, elle ne bouge pas"

    # The background stays at the back. Inside the child frame with the metal it
    # would cover the panes: a frame's regions draw below all its child frames.
    background = list(character.foreverPanel.background.values())[0]
    print("   fond du panneau : porte par %s (le cadre, pas l habillage)" % (
        background.owner._name or "?"))
    assert background.owner._name == "CharacterFrame",         "le fond doit rester sur le cadre, sinon il recouvre les volets"
    assert character.foreverPanel.topLeftCorner.owner._name != "CharacterFrame",         "le metal, lui, vit dans le cadre fils"

    # Portrait: the sweep clears the client's one, so we place ours.
    portrait = character.foreverPortrait
    pp = portrait.points[1]
    print("   portrait : %d x %d, %s sur %s (%s, %s), texture=%s" % (
        portrait.width, portrait.height, pp[1], pp[3], pp[4], pp[5],
        portrait.portraitOf))
    assert portrait.width == 48,         "48 : sur ses axes il atteint 24, la ou le metal de l anneau est opaque"
    # Computed from the top-left corner: (-18.5, 17) + (38, -38.5).
    assert pp[4] == 19.5 and pp[5] == -21.5,         "le portrait suit le trou de son anneau, porte par le coin de l encadrement"
    cornerTL = character.foreverPanel.topLeftCorner.points[1]
    assert pp[4] - cornerTL[4] == 38 and pp[5] - cornerTL[5] == -38.5,         "l ecart au coin est le centre mesure du trou, il ne doit pas deriver"
    assert portrait.portraitOf == "player", "l anneau ne doit pas rester vide"

    # The right pane background fills its pane instead of stopping at 383.
    backgroundRight = right.regions[1]
    print("   fond du volet droit : couvre tout le volet = %s" % (backgroundRight.allPoints and True))
    assert backgroundRight.allPoints, "le fond du volet droit doit remplir son volet"

    # The separator has three slices: end caps at their size, middle stretched.
    sep = right.separator
    print("   separateur : trois tranches (embouts de %d)" % sep.top.height)
    assert sep.top is not None and sep.middle is not None and sep.down is not None,         "le separateur doit etre en trois tranches, ses embouts s etalaient"
    assert sep.top.height == 4 and sep.down.height == 4
    skinLayer = character.foreverSkinLayer
    print("   separateur : niveau %d, habillage %d (il doit passer devant)" % (
        sep.frameLevel or 1, skinLayer.frameLevel or 1))
    assert (sep.frameLevel or 1) > (skinLayer.frameLevel or 1),         "le separateur disparaissait sous le metal de l encadrement"

    # Model scale is re-applied on each pass: the client resets it to 1 when the
    # character's appearance changes. The position frames the character, not the
    # scale: it moves the model back from the camera without changing its framing.
    initialPos = list(g.CharacterModelFrame.pos.values())
    print("   modele : position %s, echelle %s (laissee au client)" % (
        initialPos, g.CharacterModelFrame.modelScale))
    assert initialPos == [-6.5, 0, 0], "la profondeur retenue"
    assert g.CharacterModelFrame.modelScale is None,         "nil veut dire qu on ne touche pas a l echelle, pas qu on la remet a 1"

    # The model loads later and resets: the settings are re-applied every frame for
    # 1.5 seconds.
    recheck = g.ForeverUICharacterModelRecheck
    print("   rattrapage du modele : demande=%s, reste %.2f s" % (
        recheck.shown, recheck.rest))
    assert recheck.shown, "il doit tourner juste apres l habillage"
    lua.execute("CharacterModelFrame.pos = nil")   # loading reset everything
    recheck.scripts.OnUpdate(recheck, 0.1)
    rested = list(g.CharacterModelFrame.pos.values())
    print("   apres une image : position reposee %s" % rested)
    assert rested == [-6.5, 0, 0], "le rattrapage doit reposer le reglage"

    for _ in range(20):
        recheck.scripts.OnUpdate(recheck, 0.1)
    print("   apres deux secondes : encore actif = %s" % recheck.shown)
    assert not recheck.shown, "il doit se rendormir, pas tourner sans fin"

    # Both settings are tuned in game: the source gives no value, they are judged by
    # eye.
    g.SlashCmdList["FOREVERUI"]("model scale 0.55")
    print("   /fui modele echelle 0.55 -> %.2f" % g.CharacterModelFrame.modelScale)
    assert abs(g.CharacterModelFrame.modelScale - 0.55) < 0.001
    g.SlashCmdList["FOREVERUI"]("model position -5 0 0")
    pos = list(g.CharacterModelFrame.pos.values())
    print("   /fui modele position -5 0 0 -> (%s, %s, %s)" % (pos[0], pos[1], pos[2]))
    assert pos == [-5, 0, 0], "SetPosition(profondeur, lateral, hauteur)"
    g.SlashCmdList["FOREVERUI"]("model position default")
    print("   position rendue au client : %d rafraichissement" % g.CharacterModelFrame.refreshed)
    assert g.CharacterModelFrame.refreshed >= 1, "le client doit reprendre la main"
    g.SlashCmdList["FOREVERUI"]("model position -6.5 0 0")

    head = g.CharacterHeadSlot
    neck = g.CharacterNeckSlot
    # The model covers the whole pane and takes the mouse: at an equal level it gets
    # the click, and nothing can be unequipped.
    model = g.CharacterModelFrame
    print("   niveaux : modele %d, emplacement %d" % (
        model.frameLevel or 1, head.frameLevel or 1))
    assert (head.frameLevel or 1) > (model.frameLevel or 1),         "l emplacement doit passer au-dessus du modele, sinon le clic va au modele"
    origLevel = head.frameLevel
    g.ForeverUI.CharacterSheet.Apply()
    print("   apres un second passage : %d (pas d escalade)" % head.frameLevel)
    assert head.frameLevel == origLevel, "le niveau ne doit pas monter a chaque passage"

    print("   emplacement : %d x %d (40) | ecart vertical %d (4)" % (
        head.width, head.height, -neck.points[1][5]))
    assert head.width == 40 and head.height == 40, "PaperDollItemSlotButtonTemplate : 40"
    pt = head.points[1]
    assert (pt[1], pt[4], pt[5]) == ("TOPLEFT", 24, -60), "la colonne gauche part de (24, -60)"
    assert neck.points[1][5] == -4,         "colonnes resserrees de 2 px sur les 6 de la source, a la demande"
    # Intended deviation: the row tightens to the left, in cascade.
    left2 = g.CharacterSecondaryHandSlot.points[1][4]
    distance2 = g.CharacterRangedSlot.points[1][4]
    ammo2 = g.CharacterAmmoSlot.points[1][4]
    print("   rangee : main gauche +%d, distance +%d, munitions +%d" % (
        left2, distance2, ammo2))
    assert left2 == 4, "6 de la source moins 2, demande"
    assert distance2 == 4, "2 de plus, soit -4 a l ecran puisqu elle suit la main gauche"
    assert ammo2 == 19, "inchange : elles heritent deja des -4 de la distance"

    hands = g.CharacterHandsSlot.points[1]
    print("   colonne droite : %s (%s, %s)" % (hands[1], hands[4], hands[5]))
    assert (hands[1], hands[4], hands[5]) == ("TOPRIGHT", -20, -60), \
        "la colonne droite part de (-20, -60)"

    weapon = g.CharacterMainHandSlot.points[1]
    distance = g.CharacterRangedSlot
    ammo = g.CharacterAmmoSlot
    secondary = g.CharacterSecondaryHandSlot
    print("   armes : principale %s (%s, %s) | rangee %d/%d/%d | munitions %d a +%s" % (
        weapon[1], weapon[4], weapon[5], g.CharacterMainHandSlot.width, secondary.width,
        distance.width, ammo.width, ammo.points[1][4]))
    assert (weapon[1], weapon[4], weapon[5]) == ("BOTTOM", -60, 30), \
        "l arme principale se pose au bas du volet gauche, a (-60, 30)"
    assert g.CharacterMainHandSlot.width == secondary.width == distance.width == 40,         "les quatre emplacements de la rangee ont la meme taille, a la demande"
    assert ammo.width == 27, "les munitions gardent le petit emplacement de la source"
    assert ammo.points[1][4] == 19, "les munitions sont a 19 de la distance"

    # Title and close button, in the top bar.
    strip = character.foreverTitleStrip
    title = character.foreverTitle
    b1, b2 = strip.points[1], strip.points[2]
    print("   titre : \"%s\", bande de %s a %s, texte a %s" % (
        title.text, b1[4], b2[4], title.points[1][5]))
    assert title.text == "Robert Polson", "le titre est le nom du joueur et son titre"

    # It does not follow the shown subframe: characterFrameDisplayInfo sets
    # REPUTATION, PVP and others there; here it is always the name.
    g.ReputationFrame.Show(g.ReputationFrame)
    g.ForeverUI.CharacterSheet.Apply()
    print("   panneau de reputation ouvert : titre toujours \"%s\"" % title.text)
    assert title.text == "Robert Polson",         "la barre du haut garde le nom, quel que soit le panneau"
    g.ReputationFrame.Hide(g.ReputationFrame)
    assert b1[4] == 58 and b2[4] == -24,         "CharacterFrame n appelle pas SetTitleOffsets : les valeurs par defaut"
    assert title.points[1][5] == -5, "TitleText est a TOP (0, -5)"
    assert title.justify == "CENTER", "il se centre dans sa bande"
    assert not g.CharacterNameText.shown, "le titre du client s efface"
    assert strip.GetFrameLevel(strip) > skinLayer.GetFrameLevel(skinLayer),         "le titre passe au-dessus du metal, comme TitleContainer a 510"

    # The top bar moves the window and the position is saved: the client panel
    # system re-places the window on every open.
    print("   barre du haut : souris=%s, glissable=%s, cadre deplacable=%s" % (
        strip.mouseEnabled, strip.scripts.OnDragStart is not None, character.movable))
    assert strip.mouseEnabled, "la barre doit prendre la souris"
    assert strip.scripts.OnDragStart is not None, "la barre doit servir de poignee"
    assert character.movable, "le cadre doit etre deplacable"

    strip.scripts.OnDragStart(strip)
    character.SetPoint(character, "CENTER", g.UIParent, "CENTER", 120, -40)
    strip.scripts.OnDragStop(strip)
    saved = g.ForeverUIDB.positions["sheet"]
    print("   apres deplacement : %s (%s, %s) retenu" % (
        saved.point, saved.x, saved.y))
    assert saved.point == "CENTER" and saved.x == 120 and saved.y == -40,         "la place doit etre retenue"

    # the client re-places its window: we must put it back
    character.SetPoint(character, "TOPLEFT", g.UIParent, "TOPLEFT", 0, 0)
    g.ForeverUI.CharacterSheet.Apply()
    pp2 = character.points[len(list(character.points.values()))]
    print("   apres un passage du client : %s (%s, %s)" % (pp2[1], pp2[4], pp2[5]))
    assert (pp2[1], pp2[4], pp2[5]) == ("CENTER", 120, -40),         "la place retenue doit etre reposee apres le client"
    lua.execute('ForeverUIDB.positions["sheet"] = nil')

    # Stats, in the right pane, under the stone strip.
    l1 = g.PlayerStatFrameLeft1
    l6 = g.PlayerStatFrameLeft6
    r1 = g.PlayerStatFrameRight1
    sel = g.PlayerStatFrameLeftDropDown
    pl1 = l1.points[len(list(l1.points.values()))]
    print("   stats : ligne large de %d, premiere a (%s, %s) du volet droit" % (
        l1.width, pl1[4], pl1[5]))
    assert pl1[2].name == "ForeverUICharacterRightPane", "elles vont dans le volet droit"
    assert l1.width == 233 - 40, "elles sont elargies au volet moins ses marges"
    assert l1.height == 13, "StatFrameTemplate fait 104 x 13 : le pas vient de la"
    gap = l1.points[len(list(l1.points.values()))][5] -         g.PlayerStatFrameLeft2.points[len(list(g.PlayerStatFrameLeft2.points.values()))][5]
    print("   pas entre deux lignes : %d (13 : StatFrameTemplate)" % gap)
    assert gap == 13, "le pas est celui du modele de ligne"
    assert sel.points[len(list(sel.points.values()))][5] > pl1[5],         "le selecteur coiffe son groupe"
    y6 = l6.points[len(list(l6.points.values()))][5]
    yr1 = r1.points[len(list(r1.points.values()))][5]
    print("   second groupe %d plus bas que la derniere ligne du premier" % (y6 - yr1))
    assert yr1 < y6, "le second groupe vient sous le premier"

    # Alternating background, not from the sources: neither camelot nor 3.3.5 stripe
    # their rows. Both strips come from paperdollinfopart1c60, the only pair of
    # horizontal strips whose alpha fades at both ends.
    DARK, LIGHT = "ui-character-info-itemlevel-bounce", "ui-character-info-line-bounce"
    rects = {}
    for name in (DARK, LIGHT):
        e = lua.eval('UIAtlas.data["%s"]' % name)
        rects[name] = tuple(round(e[i], 6) for i in (2, 3, 4, 5))

    def strip(i):
        """Which of the two strips backs row i, from its texcoord rectangle."""
        background = g["PlayerStatFrameLeft" + str(i)].foreverBackground
        if background is None or background.texcoord is None:
            return None
        tc = tuple(round(v, 6) for v in background.texcoord.values())
        for name, r in rects.items():
            if tc == r:
                return "sombre" if name == DARK else "clair"
        return "?"

    strips = [strip(i) for i in range(1, 7)]
    print("   fond des lignes : %s" % " ".join(str(b) for b in strips))
    assert strips == ["sombre", "clair", "sombre", "clair", "sombre", "clair"],         "la sombre en premier, puis en alternance"
    assert g.PlayerStatFrameLeft1Label.layer == "ARTWORK",         "l intitule monte d un calque : 3.3.5 n a pas de sous-calque"
    background1 = g.PlayerStatFrameLeft1.foreverBackground
    assert background1.layer == "BACKGROUND", "et la bande reste au fond"

    # The count only includes visible rows and restarts at each category: the client
    # hides some rows depending on the chosen category.
    lua.execute('PlayerStatFrameLeft2:Hide()')
    g.ForeverUI.CharacterStatStripes()
    strips = [strip(i) for i in (1, 3, 4)]
    print("   une ligne cachee : %s" % " ".join(str(b) for b in strips))
    assert strips == ["sombre", "clair", "sombre"],         "la ligne cachee ne compte pas : pas de trou dans l alternance"
    lua.execute('PlayerStatFrameLeft2:Show()')
    g.ForeverUI.CharacterStatStripes()

    # Category selectors. Their original art overflows the frame and does not follow
    # it: it is cleared and the modern header replaces it.
    selR = g.PlayerStatFrameRightDropDown
    psel = sel.points[len(list(sel.points.values()))]
    print("   selecteur : %d x %d, %s (%s, %s), visible=%s" % (
        sel.width, sel.height, psel[1], psel[4], psel[5], sel.shown))
    assert sel.width == 203 and sel.height == 34,         "l atlas fait 201 x 32 ; elargi au volet, il deborde de 5"
    assert psel[4] == 15, "il deborde de 5 a gauche de ses lignes, posees a 20"
    assert sel.shown, "il doit etre visible"
    # camelot's UI-Character-Info-Title box, stretched.
    background = sel.foreverBackground
    print("   encadre : %s, tendu=%s" % (background.texture, bool(background.allPoints)))
    assert background is not None and background.texture is not None,         "le selecteur porte l encadre de paperdollinfopart1c60"
    assert "paperdollinfopart1c60" in background.texture,         "il vient bien de cette planche : %s" % background.texture
    assert background.allPoints,         "tendu du TOPLEFT au BOTTOMRIGHT, comme CharacterStatFrameCategoryTemplate"
    assert sel.foreverPressed is None,         "l encadre de camelot n a pas d etat presse"

    gilded = [g.PlayerStatFrameLeftDropDownLeft, g.PlayerStatFrameLeftDropDownMiddle,
            g.PlayerStatFrameLeftDropDownRight, g.PlayerStatFrameLeftDropDownText]
    print("   cadre dore efface : %s" % [bool(r.shown) for r in gilded])
    assert not any(r.shown for r in gilded), "l art du menu deroulant deborde : il s efface"
    arrow = g.PlayerStatFrameLeftDropDownButton
    print("   fleche du menu masquee : %s" % (not arrow.shown))
    assert not arrow.shown, "toute la barre ouvre le menu, la fleche n a plus lieu d etre"

    # The pressed-state logic stays in place but finds nothing to press: camelot's
    # box has no such state.
    lua.execute('UIDROPDOWNMENU_OPEN_MENU = PlayerStatFrameLeftDropDown')
    lua.execute('DropDownList1:Show()')
    g.ForeverUI.CharacterStatTabsState()
    print("   ancrage de la liste : %s sur %s de %s, ecart (%s, %s)" % (
        sel.point, sel.relativePoint, sel.relativeTo and sel.relativeTo._name,
        sel.xOffset, sel.yOffset))
    assert (sel.point, sel.relativePoint) == ("TOPLEFT", "BOTTOMLEFT"),         "la liste tombe sous le bouton, cale a gauche"
    assert sel.xOffset == 0 and sel.yOffset == 0, "sans ecart"
    assert sel.relativeTo._name == "PlayerStatFrameLeftDropDown",         "sur le bouton, pas sur sa piece doree que nous avons masquee"

    # The client resizes the selector each time the menu opens.
    lua.execute('UIDropDownMenu_Initialize(PlayerStatFrameLeftDropDown)')
    g.ForeverUI.CharacterStatTabsSize(g.PlayerStatFrameLeftDropDown)
    print("   apres ouverture du menu : %d x %d" % (sel.width, sel.height))
    assert sel.width == 203 and sel.height == 34,         "UIDropDownMenu_InitializeHelper repose la hauteur : on repasse derriere"

    lua.execute('DropDownList1:Hide()')
    g.ForeverUI.CharacterStatTabsState()
    assert sel.mouseEnabled and sel.scripts.OnMouseUp is not None,         "toute la barre ouvre le menu, pas seulement la fleche de 24"
    print("   intitules : gauche \"%s\" | droite \"%s\"" % (
        sel.foreverLabel.text, selR.foreverLabel.text))
    assert sel.foreverLabel.text == "Attributs",         "l intitule est la categorie de la CVar, pas sa cle"
    assert selR.foreverLabel.text == "Corps a corps"
    lua.execute('UpdatePaperdollStats("PlayerStatFrameLeft", "PLAYERSTAT_DEFENSES")')
    print("   apres changement de categorie : gauche \"%s\"" % sel.foreverLabel.text)
    assert sel.foreverLabel.text == "Defenses",         "l intitule doit suivre le menu du client"

    close = g.CharacterFrameCloseButton
    pf = close.points[1]
    print("   fermeture : %d x %d, %s (%s, %s)" % (
        close.width, close.height, pf[1], pf[4], pf[5]))
    assert close.width == 24 and close.height == 24
    assert (pf[1], pf[4], pf[5]) == ("TOPRIGHT", 1, 0),         "le bouton de fermeture va au coin haut droit"
    assert close._normal.texture is not None, "il porte le X rouge des panneaux"

    # Side tabs: in a column on the right, outside the window.
    bar = g.ForeverUICharacterModeTabs
    o1, o2 = g.CharacterFrameTab1, g.CharacterFrameTab2
    pb = bar.points[1]
    print("   onglets : barre %d x %d, %s sur %s (%s, %s)" % (
        bar.width, bar.height, pb[1], pb[3], pb[4], pb[5]))
    assert bar.width == 64 and bar.height == 384, "ModeTabs fait 64 x 384"
    assert pb[1] == "TOPLEFT" and pb[3] == "TOPRIGHT" and pb[5] == -30,         "la barre se pose a droite du cadre, 30 sous son haut"
    assert pb[4] == 1, "decalee d un pixel vers la droite, a la demande"
    print("   un onglet : %d x %d (55 x 55 : 55 x 60 moins 5 de transparent)" % (
        o1.width, o1.height))
    assert o1.width == 55 and o1.height == 55
    # Under the border. The tab's left tongue, covered by the hover and the active
    # marker, slides under the window; otherwise it overlaps the right pane's metal.
    skinFrame = character.foreverSkinLayer
    print("   niveaux : barre %d, onglet %d, habillage %d" % (
        bar.frameLevel or 0, o1.frameLevel or 0, skinFrame.frameLevel or 0))
    assert (o1.frameLevel or 0) < (skinFrame.frameLevel or 0),         "un onglet doit passer SOUS l encadrement de la fenetre"
    assert (g.ForeverUICharacterTabPvP.frameLevel or 0) < (skinFrame.frameLevel or 0),         "les notres aussi"
    assert (o1.frameLevel or 0) > (character.frameLevel or 0),         "mais au-dessus du fond du panneau"
    p2 = o2.points[1]
    assert p2[1] == "TOPLEFT" and p2[3] == "BOTTOMLEFT", "ils s empilent"
    # Without a pet, the next tabs move up. A hidden but still anchored tab would
    # leave a gap of its height under the character tab.
    lua.execute("HAS_PET = false")
    g.PetPaperDollFrame_UpdateIsAvailable()
    o3 = g.CharacterFrameTab3
    p3 = o3.points[len(list(o3.points.values()))]
    print("   sans familier : onglet 3 ancre %s sur %s de %s (%s, %s)" % (
        p3[1], p3[3], p3[2].name, p3[4], p3[5]))
    assert not g.CharacterFrameTab2.shown, "le client masque l onglet du familier"
    assert p3[2].name == "CharacterFrameTab1",         "reputation doit suivre le personnage, pas le trou du familier"
    assert (p3[1], p3[3]) == ("TOPLEFT", "BOTTOMLEFT") and (p3[4], p3[5]) == (0, -2),         "et avec le meme espace que les autres : UpdateTabLayout pose (0, -2)"
    p4 = g.CharacterFrameTab4.points[len(list(g.CharacterFrameTab4.points.values()))]
    assert p4[2].name == "CharacterFrameTab3", "les competences suivent a leur tour"

    # When the pet returns, the stack closes back.
    lua.execute("HAS_PET = true")
    g.PetPaperDollFrame_UpdateIsAvailable()
    p3 = o3.points[len(list(o3.points.values()))]
    print("   familier revenu : onglet 3 ancre sur %s" % p3[2].name)
    assert p3[2].name == "CharacterFrameTab2", "il reprend sa place derriere le familier"

    # Tab icons. Only the skills icon could be exported: the wow.export listfile does
    # not name the two INV_SideTab_*_c60 files.
    o4 = g.CharacterFrameTab4
    print("   onglet competences : icone=%s, texte visible=%s" % (
        o4.foreverIcon.texture, g.CharacterFrameTab4Text.shown))
    assert "TabIcons" in o4.foreverIcon.texture,         "l icone affichee est la version CUITE, pas l export brut"
    assert o4.foreverIcon.texture and "JackofAllTrades" in o4.foreverIcon.texture,         "CHARACTER_MODE_TAB_ICONS donne cette icone aux competences"
    assert o4.foreverIcon.shown and not g.CharacterFrameTab4Text.shown,         "l icone remplace le mot"
    for i, expected in ((3, "Reputation2"), (5, "Currency")):
        tab = g["CharacterFrameTab%d" % i]
        print("   onglet %d : icone=%s, texte visible=%s" % (
            i, tab.foreverIcon.texture, g["CharacterFrameTab%dText" % i].shown))
        assert tab.foreverIcon.texture and expected in tab.foreverIcon.texture,             "l icone de camelot, versee par son FileDataID : onglet %d" % i
        assert tab.foreverIcon.shown and not g["CharacterFrameTab%dText" % i].shown,             "elle remplace le mot : onglet %d" % i
    # Rotating the model with the mouse: 0.008 radian per UI unit, eased at 0.15 per
    # frame (camelot, OrbitCameraMixin).
    for name in ("CharacterModelFrame", "PetModelFrame"):
        lua.execute("""
            local m = %s
            m.rotation = 0.61
            MOUSE_X = 100 * UIParent:GetEffectiveScale()
            m.hooks.OnMouseDown(m, "LeftButton")
            MOUSE_X = 150 * UIParent:GetEffectiveScale()
            m.hooks.OnUpdate(m, 1 / 60)
        """ % name)
        m = g[name]
        one = m.rotation
        lua.execute("local m = %s for i = 1, 200 do m.hooks.OnUpdate(m, 1 / 60) end" % name)
        print("modele %s : apres 50 unites, %.4f puis %.4f (cible %.4f), souris=%s" % (name, one, m.rotation, 0.61 + 50 * 0.008,
            m.mouseEnabled))
        assert abs(one - (0.61 + 0.15 * 0.4)) < 1e-9, "premiere image : 15 % du chemin"
        assert abs(m.rotation - (0.61 + 0.4)) < 1e-6 and m.mouseEnabled
        lua.execute("local m = %s m.hooks.OnMouseUp(m, 'LeftButton') m.hooks.OnUpdate(m, 1 / 60) MOUSE_X = nil" % name)
        assert m.foreverTarget is None and m.foreverCursor is None, "relachee : plus rien ne bouge"
    # camelot has no pet tab icon: one per class instead (the bench plays a death
    # knight).
    ic2 = g.CharacterFrameTab2.foreverIcon
    print("onglet du familier : icone=%s, texte visible=%s" % (ic2.texture, g.CharacterFrameTab2Text.shown))
    assert ic2.shown and ic2.texture.endswith("Spell_Shadow_AnimateDead") and not g.CharacterFrameTab2Text.shown

    print("   onglet du personnage : icone=%s, texte masque=%s" % (
        o1.foreverIcon.texture.split(chr(92))[-1], not g.CharacterFrameTab1Text.shown))
    # Deviation from the source: camelot shows the portrait here.
    assert o1.foreverIcon.texture == "Interface" + chr(92) + "ForeverUI" + chr(92)         + "TabIcons" + chr(92) + "ClassIcon_" + g.STATE.classToken,         "l onglet du personnage porte l icone de SA classe, cuite comme les autres"
    assert not g.CharacterFrameTab1Text.shown, "et le mot s en va"
    assert abs(o1.foreverIcon.texcoord[1] - 0.03125) < 1e-6,         "le rognage reste : la cuisson a ete calculee en le supposant"

    # Level, race and class: in the right pane, where the source puts
    # PaperDollLevelInfo.
    level = right.levelRow
    pn = level.points[1]
    assert not g.CharacterLevelText.shown, "la ligne du client s efface"
    # Without the race: rebuilt from UNIT_LEVEL_TEMPLATE and the class name, like
    # camelot's PLAYER_LEVEL_NO_SPEC, which this client lacks.
    print("   ligne de niveau : \"%s\" (le client disait \"%s\")" % (
        level.text, g.CharacterLevelText.text))
    expected = "Level %d %s" % (g.STATE.level, g.STATE.className)
    assert level.text == expected, "niveau et classe, sans la race"
    assert "Elfe" not in level.text, "la race ne doit plus y etre"
    print("   ligne de niveau : %s sur %s (%s, %s), large de %d, parent %s" % (
        pn[1], pn[3], pn[4], pn[5], level.width, level.parent and level.parent._name))
    assert pn[1] == "TOP" and pn[3] == "TOP", "elle se pose sous le haut du volet"
    assert pn[5] == -54, "PaperDollLevelInfo : -4 des onglets lateraux, -50 dessous"

    # The pane's three tabs, above the level line.
    #
    # camelot/PaperDollFrame_UpdateSidebarTabLayout: with three tabs, the second one
    # holds the anchor, at TOP of the tab frame (0, -5); the third sticks to its right,
    # the first to its left. With two, it recenters by shifting the second by half a
    # width.
    stats, gear = right.statsTab, right.equipmentTab
    titles = right.titlesTab
    ps, pg, pt = stats.points[1], gear.points[1], titles.points[1]
    print("   onglets du volet : %dx%d, equipement %s (%s, %s), stats %s sur %s,"
          " titres %s sur %s" % (stats.width, stats.height, pg[1], pg[4], pg[5],
                                 ps[1], ps[3], pt[1], pt[3]))
    assert stats.width == 42 and stats.height == 42,         "PaperDollSidebarTabTemplate fait 42 x 42"
    assert (pg[1], pg[4], pg[5]) == ("TOP", 0, -9),         "a trois, c est le deuxieme qui porte l ancre, et le groupe est centre"
    assert (ps[1], ps[3]) == ("RIGHT", "LEFT"), "les statistiques a sa gauche"
    assert (pt[1], pt[3]) == ("LEFT", "RIGHT"), "les titres a sa droite"

    print("   icones : stats=%s rogne a %.6f | equipement=%s" % (
        stats.icon.portraitOf, stats.icon.texcoord[1], gear.icon.texture))
    assert stats.icon.portraitOf == "player",         "PAPERDOLL_SIDEBARTAB_STATS : icon = nil, il prend le portrait"
    # Pane tab icons keep their own size; the side tab icon size (similar name) must
    # not drive them.
    print("   icones des onglets du volet : %d x %d" % (
        stats.icon.width, gear.icon.width))
    assert stats.icon.width == 28 and gear.icon.width == 28,         "ces deux-la font 28, et rien ne doit les entrainer"
    assert abs(stats.icon.texcoord[1] - 0.109375) < 1e-6,         "le rognage de la source"
    assert gear.icon.texture and "GearManager" in gear.icon.texture,         "PaperDollSidebarTabs.blp n existe pas ici : UI-GearManager-Button le remplace"
    tc = list(gear.icon.texcoord.values())
    print("   icone du gestionnaire rognee a (%.4f, %.4f, %.4f, %.4f)" % (
        tc[0], tc[1], tc[2], tc[3]))
    assert abs(tc[0] - 6 / 64) < 1e-6 and abs(tc[1] - 58 / 64) < 1e-6,         "le carre central : l art fait 52 de large pour 64 de haut"
    assert abs(tc[2] - tc[0]) < 1e-6 and abs(tc[3] - tc[1]) < 1e-6,         "la meme plage sur les deux axes, sinon il reste rectangulaire"
    assert stats.selected.shown and not gear.selected.shown,         "l onglet des statistiques est celui qui est ouvert"

    print("   bouton d origine du gestionnaire masque : %s" % (not g.GearManagerToggleButton.shown))
    assert not g.GearManagerToggleButton.shown, "c est l onglet qui ouvre le panneau"
    # They act as tabs: opening one closes the other.
    gear.scripts.OnClick(gear)
    rows = [g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7)]
    print("   clic gestionnaire : panneau=%s, stats visibles=%s, marque=%s" % (
        g.GearManagerDialog.shown, any(rows), gear.selected.shown))
    assert g.GearManagerDialog.shown, "l onglet ouvre le GearManagerDialog du client"
    assert not any(rows), "et masque les statistiques"
    assert not g.PlayerStatFrameLeftDropDown.shown, "les selecteurs aussi"
    assert gear.selected.shown and not stats.selected.shown, "la marque passe sur lui"
    assert g.ForeverUIEquipmentPane.shown,         "le panneau du gestionnaire se montre avec son onglet"

    # A skin pass must not show them again behind our back.
    g.ForeverUI.CharacterSheet.Apply()
    assert not g.PlayerStatFrameLeftDropDown.shown,         "l habillage repasse ici a chaque evenement : il doit respecter l onglet"

    # The equipment manager calls UpdateUIPanelPositions: the saved position must
    # survive it.
    lua.execute('ForeverUIDB.positions["sheet"] = '
                '{ point = "CENTER", relativePoint = "CENTER", x = 120, y = -40 }')
    g.UpdateUIPanelPositions(g.CharacterFrame)
    pp2 = character.points[len(list(character.points.values()))]
    print("   apres le systeme de panneaux : %s (%s, %s)" % (pp2[1], pp2[4], pp2[5]))
    assert (pp2[1], pp2[4], pp2[5]) == ("CENTER", 120, -40),         "ouvrir le gestionnaire ne doit pas reinitialiser la fenetre"
    lua.execute('ForeverUIDB.positions["sheet"] = nil')

    stats.scripts.OnClick(stats)
    rows = [g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7)]
    print("   clic statistiques : panneau=%s, stats visibles=%s, marque=%s" % (
        g.GearManagerDialog.shown, all(rows), stats.selected.shown))
    assert all(rows) and g.PlayerStatFrameLeftDropDown.shown, "elles reviennent"
    assert not g.GearManagerDialog.shown, "et le panneau du gestionnaire se ferme"
    assert stats.selected.shown and not gear.selected.shown, "la marque revient sur lui"
    print("   panneau du gestionnaire masque sous les statistiques : %s" % (
        not g.ForeverUIEquipmentPane.shown))
    assert not g.ForeverUIEquipmentPane.shown,         "ses boutons sont ses cadres fils : masquer la fenetre du client ne suffit pas"
    new = g.ForeverUIEquipmentNewSet
    print("   bouton New Set : \"%s\", %d tranches normales, %d pressees" % (
        new.text, len(list(new.foreverNormal.values())),
        len(list(new.foreverPressed.values()))))
    assert new.text == "New Set",         "ecrit en dur : ce client ne porte aucune chaine equivalente"
    assert len(list(new.foreverNormal.values())) == 9,         "le meme bouton tertiaire que les selecteurs, decoupe"
    assert new.scripts.OnMouseDown or new.hooks.OnMouseDown,         "l etat presse suit le bouton de la souris"
    # It is declared toplevel and raises itself on every open: the button level must
    # be recomputed afterwards, not set once.
    lua.execute("GearManagerDialog_OnShow()")
    g.ForeverUI.EquipmentPane.Apply()
    print("   niveaux apres une ouverture : fenetre %d, bouton %d, toplevel=%s" % (
        g.GearManagerDialog.frameLevel or 1, new.frameLevel or 1,
        g.GearManagerDialog.toplevel))
    assert g.GearManagerDialog.toplevel is False,         "elle n est plus une fenetre : elle ne doit plus se hisser"
    assert (new.frameLevel or 1) > (g.GearManagerDialog.frameLevel or 1),         "la fenetre du client couvre le panneau et prend la souris"
    assert new.scripts.OnClick is not None, "et il porte bien son clic"
    assert pn[2].name == "ForeverUICharacterRightPane", "dans le volet DROIT"
    assert level.owner._name == "ForeverUICharacterRightPane",         "elle appartient au volet : une region ne se reparente pas en 3.3.5"
    assert level.width == 220, "PaperDollLevelInfo fait 220 de large"
    assert level.justify == "CENTER", "centree"

    # Model arrows: centered on the pane, side by side.
    fg = g.CharacterModelFrameRotateLeftButton.points[1]
    fd = g.CharacterModelFrameRotateRightButton.points[1]
    print("   fleches : %s (%s) et %s (%s), a %s du haut du volet" % (
        fg[1], fg[4], fd[1], fd[4], fg[5]))
    assert fg[1] == "TOP" and fd[1] == "TOP", "elles s accrochent au haut du volet"
    assert fg[2].name == "ForeverUICharacterLeftPane"
    assert abs(fg[4] + fd[4]) < 1e-6, "elles se repartissent de part et d autre du milieu"
    assert fg[4] < 0 and fd[4] > 0, "la gauche a gauche, la droite a droite"

    model = g.CharacterModelFrame.points[1]
    print("   modele : %s sur %s, remonte de %s dans son volet" % (
        model[1], model[3], model[5]))
    assert model[1] == "TOPLEFT" and model[2].name == "ForeverUICharacterLeftPane",         "le modele occupe le volet gauche"
    assert model[5] == 24, "il est remonte dans son volet"

    # The resistance panel is shifted exactly once: always from its original anchor,
    # never from the current position.
    res = g.CharacterResistanceFrame
    x1 = res.points[len(list(res.points.values()))][4]
    g.ForeverUI.CharacterSheet.Apply()
    g.ForeverUI.CharacterSheet.Apply()
    x2 = res.points[len(list(res.points.values()))][4]
    print("   resistances : %s, puis %s apres deux passages de plus" % (x1, x2))
    assert x1 == -60 + 30, "le decalage est de 30 vers la droite"
    assert x1 == x2, "le decalage ne doit pas deriver a chaque passage"

    # Right pane collapse.
    collapse = g.ForeverUICharacterRightPaneToggle
    pr = collapse.points[1]
    print("   bouton de repli : %d x %d, %s sur %s de %s (%s, %s)" % (
        collapse.width, collapse.height, pr[1], pr[3], pr[2].name, pr[4], pr[5]))
    assert collapse.width == 28 and collapse.height == 28, "28 x 28, comme la source"
    assert pr[1] == "TOPRIGHT" and pr[3] == "TOPRIGHT",         "au coin haut droit du volet gauche"
    assert pr[2].name == "ForeverUICharacterLeftPane", "du volet GAUCHE, comme LeftPaneHost"
    assert (pr[4], pr[5]) == (-6, -6), "decale de -6 sur les deux axes"
    # The model covers this corner and takes the mouse at an equal level: the same
    # trap as the equipment slots.
    print("   niveaux : bouton %d, modele %d" % (
        collapse.frameLevel or 1, g.CharacterModelFrame.frameLevel or 1))
    assert (collapse.frameLevel or 1) > (g.CharacterModelFrame.frameLevel or 1),         "sinon le modele recoit le clic"
    assert collapse._normal.texture.endswith("PrevPage-Up"),         "depliee, la fleche montre vers la gauche"

    # Collapse. The open tab is the equipment manager's: expanding must bring it back,
    # not reopen the stats.
    gear.scripts.OnClick(gear)
    collapse.scripts.OnClick(collapse)
    rows = [g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7)]
    print("   replie : fenetre %d de large, volet droit visible=%s, stats=%s, "
          "gestionnaire=%s, onglets lateraux=%s" % (
        character.width, right.shown, any(rows), g.GearManagerDialog.shown, bar.shown))
    assert character.width == 398, "CHARACTER_FRAME_COLLAPSED_WIDTH, la largeur du volet gauche"
    assert not right.shown, "le volet droit s en va"
    assert not any(rows), "les lignes de statistiques sont au client : a masquer une a une"
    assert not g.PlayerStatFrameLeftDropDown.shown, "les selecteurs aussi"
    assert not g.GearManagerDialog.shown, "et le panneau du gestionnaire"
    assert bar.shown, "LES ONGLETS LATERAUX RESTENT VISIBLES"
    assert g.CharacterModelFrame.shown, "le volet gauche ne bouge pas"
    assert collapse._normal.texture.endswith("NextPage-Up"),         "replie, la fleche montre vers la droite"
    assert g.ForeverUIDB.rightPaneCollapsed is True, "l etat est retenu"

    # A skin pass must not expand it again behind our back.
    g.ForeverUI.CharacterSheet.Apply()
    print("   apres un passage de l habillage : %d de large" % character.width)
    assert character.width == 398, "l habillage repasse a chaque evenement : il doit respecter le repli"
    assert not right.shown and not any(
        g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7))

    # Expand: the equipment manager tab comes back, not the stats one.
    collapse.scripts.OnClick(collapse)
    rows = [g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7)]
    print("   deplie : %d de large, volet droit=%s, gestionnaire=%s, stats=%s" % (
        character.width, right.shown, g.GearManagerDialog.shown, any(rows)))
    assert character.width == 631, "la fenetre reprend sa largeur"
    assert right.shown, "le volet droit revient"
    assert g.GearManagerDialog.shown, "et l onglet qui etait ouvert avec lui"
    assert not any(rows), "les statistiques ne se rouvrent pas d office"
    assert g.ForeverUIDB.rightPaneCollapsed is False

    # And from the stats tab, the stats come back.
    stats.scripts.OnClick(stats)
    collapse.scripts.OnClick(collapse)
    collapse.scripts.OnClick(collapse)
    rows = [g["PlayerStatFrameLeft" + str(i)].shown for i in range(1, 7)]
    print("   replie puis deplie depuis les statistiques : stats=%s, gestionnaire=%s" % (
        all(rows), g.GearManagerDialog.shown))
    assert all(rows), "les statistiques reviennent"
    assert not g.GearManagerDialog.shown, "et le gestionnaire reste ferme"

    # Side tabs switch whole screens.
    #
    # The equipment manager panel belongs to our pane, which the client's
    # PaperDollFrame does not hide; and the client reputation frame keeps the original
    # window size, so its bars would cross the right pane.
    Panes = g.ForeverUI.Panes
    gear.scripts.OnClick(gear)          # equipment manager open
    assert g.ForeverUIEquipmentPane.shown

    g.CharacterFrame_ShowSubFrame("ReputationFrame")
    g.ForeverUI.Panes.ShowGroup("ReputationFrame")
    g.ForeverUI.CharacterApplyPanes(character)
    pr2 = g.ReputationFrame.points[len(list(g.ReputationFrame.points.values()))]
    print("   onglet reputation : volet droit=%s, pierre=%s, onglets de page=%s, "
          "panneau=%s, fenetre %d, reputation ancree a %s de %s" % (
        right.shown, right.stone.shown, stats.shown,
        g.ForeverUIEquipmentPane.shown, character.width, pr2[1], pr2[2].name))
    assert not g.ForeverUIEquipmentPane.shown,         "LE PANNEAU DU GESTIONNAIRE NE SURVIT PLUS A UN CHANGEMENT D ONGLET"
    assert not g.GearManagerDialog.shown, "ni la fenetre du client avec lui"
    # The right pane stays open: each tab puts its own content there. Only what
    # belongs to the character goes away.
    assert right.shown, "LE VOLET DROIT RESTE OUVERT D UN ONGLET A L AUTRE"
    assert character.width == 631, "la fenetre garde donc sa largeur"
    assert not right.stone.shown,         "la bande de pierre porte les onglets de page : elle ne sert plus ici"
    assert not stats.shown and not gear.shown,         "les deux onglets de page appartiennent au personnage"
    assert not right.levelRow.shown, "la ligne de niveau aussi"
    assert pr2[2].name == "ForeverUICharacterLeftPane",         "LES BARRES DE REPUTATION SONT BORNEES AU VOLET GAUCHE"
    assert g.ReputationFrame.shown, "et l ecran de reputation, lui, parait"
    assert character.foreverCollapse.shown,         "le volet existe sur cet onglet : il reste repliable"

    # Reputation tab: our own rows, built from camelot's templates and filled from
    # GetFactionInfo. The client rows are removed, which stops them redrawing their art.
    lua.execute("ForeverUICharacterLeftPane:SetHeight(464)")
    g.CharacterFrame_ShowSubFrame("ReputationFrame")
    g.ForeverUI.Panes.ShowGroup("ReputationFrame")
    g.ForeverUI.CharacterApplyPanes(character)

    list_ = g.ForeverUIReputationList
    # The client answers beyond its count: stop at the count.
    placedCount = [l.name.text for l in g.ForeverUI.ReputationTab.Rows.values() if l.shown]
    print("   posees : %s (le client en annonce %d, et repond a %d)" % (
        placedCount, g.GetNumFactions(), g.GetNumFactions() + 1))
    assert len(placedCount) == g.GetNumFactions(),         "une ligne par faction annoncee, pas une de plus"
    assert "Inactive" not in placedCount, "l entree hors compte ne doit pas paraitre"
    pl = list_.points[1]
    ranks = g.ForeverUI.ReputationTab.Rows
    r1, r2 = g.ForeverUIReputationRow1, g.ForeverUIReputationRow2
    print("   reputation : liste %s (%s, %s), %d lignes de %d de large" % (
        pl[1], pl[4], pl[5], len(list(ranks.values())), r1.width))
    assert (pl[4], pl[5]) == (10, -40), "TOPLEFT du volet (10, -40)"
    p1 = r1.points[len(list(r1.points.values()))]
    # SetPadding: a margin of 10, plus the template indent.
    assert r1.width == 378 - 2 * 10, "la liste moins ses deux marges de 10 (sans barre, elle prend sa place : 363 + 15)"
    assert list_.points[len(list(list_.points.values()))][4] == -10, "sans barre, bord droit a la marge de gauche"
    assert (p1[4], p1[5]) == (10, -10), "TOPLEFT du panneau, decale de la marge"
    assert not g.ReputationBar1.shown, "les lignes du client s en vont"

    # Header: plate, gold name at LEFT x = 10, arrow at RIGHT (-8, -1).
    pf = r1.arrow.points[1]
    pn1 = r1.name.points[1]
    print("   en-tete : plaque=%s barre=%s | nom %s x=%s, police=%s | fleche %s (%s, %s)" % (
        r1.plate.shown, r1.bar.shown, pn1[1], pn1[4], r1.name.font,
        pf[1], pf[4], pf[5]))
    slices = list(r1.plate.values())
    print("   plaque : %d tranches, %d visibles sur l en-tete, %d sur l entree" % (
        len(slices), sum(1 for t in slices if t.shown),
        sum(1 for t in r2.plate.values() if t.shown)))
    assert len(slices) == 9, "la plaque se decoupe en neuf, elle ne s etire pas"
    assert all(t.shown for t in slices), "toutes paraissent sur un en-tete"
    assert not any(t.shown for t in r2.plate.values()), "aucune sur une entree"
    assert not r1.bar.shown, "un en-tete n a pas de barre"
    assert (pn1[1], pn1[4]) == ("LEFT", 10), "ReputationHeaderTemplate : LEFT x = 10"

    # The three templates and their indents, as SetElementFactory and
    # SetElementIndentCalculator give them.
    r3 = g.ForeverUIReputationRow3
    def indent(row):
        pt = row.points[len(list(row.points.values()))]
        return pt[4] - 10          # minus the margin of 10
    print("   hierarchie : en-tete h=%d retrait=%d | sous-en-tete h=%d retrait=%d "
          "| entree enfant h=%d retrait=%d" % (
        r1.height, indent(r1), r2.height, indent(r2), r3.height, indent(r3)))
    assert (r1.height, indent(r1)) == (28, 0),         "en-tete de premier niveau : 28 de haut, aucun retrait"
    assert (r2.height, indent(r2)) == (22, 2),         "sous-en-tete : ReputationSubHeaderTemplate, 22 de haut, retrait 2"
    assert (r3.height, indent(r3)) == (30, 46),         "enfant qui n est pas un en-tete : 30 de haut, retrait 46"
    assert r2.chevron.shown and not r2.arrow.shown,         "un sous-en-tete porte son bouton a GAUCHE"
    assert r1.arrow.shown and not r1.chevron.shown,         "un en-tete de premier niveau porte sa fleche a DROITE"
    assert r2.bar.shown, "ce sous-en-tete a de la reputation : sa barre parait"
    assert r3.bar.shown and not r3.chevron.shown, "une entree n a ni l un ni l autre"

    # The gap between two rows is 3 and follows the row heights.
    gap = (-indent(r1) - 10) + 0
    y1 = r1.points[len(list(r1.points.values()))][5]
    y2 = r2.points[len(list(r2.points.values()))][5]
    print("   ecart : ligne 1 a %s, ligne 2 a %s (28 + 3 attendus)" % (y1, y2))
    assert y1 - y2 == 28 + 3, "elementSpacing = 3, apres une ligne de 28"

    # The whole client screen stays hidden, not only its rows: its scroll list,
    # column labels and tree lines.
    for name in ("ReputationBar1", "ReputationListScrollFrame",
                "ReputationFrameCollapseAll"):
        g[name].Show(g[name])
    g.ForeverUI.ReputationLayout()
    remaining = [n for n in ("ReputationBar1", "ReputationListScrollFrame",
                            "ReputationFrameCollapseAll") if g[n].shown]
    print("   ecran du client : %d morceau(x) encore visible(s)" % len(remaining))
    assert remaining == [], "il en reste : %s" % remaining
    assert g.ForeverUIReputationList.shown, "mais notre panneau demeure"
    assert g.ReputationDetailFrame.shown,         "et le cadre de detail aussi : il a change de parent, il vit a droite"
    lines = [t for t in g.ForeverUIReputationList.regions.values() if t.width == 384]
    assert len(lines) == 2,         "nos deux traits vivent sur notre panneau, hors d atteinte du balayage"
    assert r1.name.font == "GameFontNormalLeft", "et son nom est en or"
    assert (pf[1], pf[4], pf[5]) == ("RIGHT", -8, -1), "StateIcon a RIGHT (-8, -1)"
    assert r1.arrow.width == 13, "common-button-list-minus, a sa taille d atlas"

    # An entry: bar at RIGHT x = -3, white name at x = 15, i.e. the AccountWideIcon
    # right edge (25) minus the 10 that Initialize removes when that icon is hidden,
    # which it always is here.
    pb = r3.bar.points[1]
    pn2 = r3.name.points[1]
    print("   entree : barre %d x %d %s x=%s | nom x=%s police=%s | remplissage %s" % (
        r3.bar.width, r3.bar.height, pb[1], pb[4], pn2[4],
        r3.name.font, r3.bar.fill.width))
    assert r3.bar.width == 160 and r3.bar.height == 29, "ReputationBarTemplate"
    assert (pb[1], pb[4]) == ("RIGHT", -3), "ancree RIGHT x = -3"
    assert (pn2[1], pn2[4]) == ("LEFT", 15), "25 moins les 10 de Initialize"
    assert r3.name.font == "GameFontHighlight", "le nom d une entree est en blanc"
    r4 = g.ForeverUIReputationRow4
    print("   exalte : barre pleine (%s) | neutre : %s sur 160" % (
        r4.bar.fill.width, r3.bar.fill.width))
    assert r4.bar.fill.width == 160.0,         "a l attitude maximale la barre est pleine, comme la source le veut"
    assert r3.bar.fill.width == 40.0, "250 sur 1000, sur 160 de barre"
    assert r2.bar.fill.height == 15, "ColoredProgressBarTemplate"
    # The gauge background is sliced, the fill is not: one is a frame, the other a
    # gauge that camelot crops to the fraction.
    backgrounds = [t for t in r3.bar.regions.values() if t.layer == "BACKGROUND"]
    print("   jauge : %d tranches de fond, remplissage %s de large" % (
        len(backgrounds), r3.bar.fill.width))
    assert len(backgrounds) == 9, "common-stat-bar-bg se decoupe en neuf"
    assert r3.bar.fill.layer == "BORDER",         "le remplissage reste une seule texture, rognee"
    assert "statbarfill" in (r3.bar.fill.texture or ""),         "et c est la version CUITE au masque, decoupee comme le fond"
    assert abs(r3.bar.fill.texcoord[2] - 0.25) < 1e-6,         "rognee a la fraction : 250 sur 1000"

    # Click: a header collapses, an entry is selected.
    # Collapsing shortens the list: the client drops the children from its numbering
    # instead of hiding them, so everything below moves up.
    before = [l.name.text for l in ranks.values() if l.shown]
    r2.scripts.OnClick(r2)                  # the Alliance subheader
    g.ForeverUI.ReputationLayout()
    after = [l.name.text for l in ranks.values() if l.shown]
    print("   repli d Alliance : %s -> %s" % (before, after))
    assert after == ["Classic", "Alliance"],         "ses deux enfants quittent la liste, le reste reste en place"
    assert "Inactive" not in after,         "on s arrete a GetNumFactions : le client repond au-dela, mais pas nous"
    assert r2.chevron.height == 13, "le plus prend la place du moins, a SA taille"

    r2.scripts.OnClick(r2)                  # expand it again
    g.ForeverUI.ReputationLayout()
    assert [l.name.text for l in ranks.values() if l.shown] == before,         "deplier la rend telle quelle"

    r1.scripts.OnClick(r1)                  # the top-level header
    g.ForeverUI.ReputationLayout()
    print("   repli de Classic : %s" % [l.name.text for l in ranks.values() if l.shown])
    assert [l.name.text for l in ranks.values() if l.shown] == ["Classic"],         "tout le bloc s en va"
    r1.scripts.OnClick(r1)
    g.ForeverUI.ReputationLayout()

    r3.scripts.OnClick(r3)
    g.ForeverUI.ReputationLayout()
    print("   clic sur une entree : survol a %.2f sur %s" % (
        r3.hover.alpha, r3.name.text))
    assert abs(r3.hover.alpha - 0.20) < 1e-6,         "RefreshBackgroundHighlightOpacity : 0,20 pour la ligne choisie"
    assert abs(r1.hover.alpha) < 1e-6, "un en-tete n a pas de survol"

    # Names are left-aligned whatever the template.
    #
    # SetFontObject resets the justification: GameFontHighlight has no justifyH, so
    # it centers, and the name would be centered in a box whose width changes with the
    # template, shifting sideways while scrolling. camelot sets the justification on
    # top of the font object:
    #   <FontString inherits="GameFontHighlight" justifyH="LEFT">
    alignments = {}
    for rank, row in ranks.items():
        if row.shown:
            alignments[row.name.text] = (row.name.font, row.name.justify)
    print("   noms : %s" % ", ".join(
        "%s=%s/%s" % (n, str(f).replace("GameFont", ""), j)
        for n, (f, j) in sorted(alignments.items())))
    assert alignments, "il faut des lignes posees pour juger"
    assert all(j == "LEFT" for _, j in alignments.values()),         "en-tete, sous-en-tete et entree : tous cales a gauche"

    # A faction at war: the highlight is red, not white.
    #
    # camelot: RefreshBackgroundHighlightColor uses FACTION_AT_WAR_COLOR, which does
    # not exist in 3.3.5. The value comes from the modern client's GlobalColor.db2:
    # 0xFF690300, i.e. 105, 3, 0.
    def veil(row):
        return [round(v, 6) for v in row.hoverPieces[1].vertex.values()]

    print("   hors guerre : voile %s, alpha %.2f" % (veil(r3), r3.hover.alpha))
    assert veil(r3) == [1.0, 1.0, 1.0], "hors guerre, WHITE_FONT_COLOR"

    lua.execute('ALL_FACTIONS[3].guerre = true')
    g.ForeverUI.ReputationLayout()
    red = [round(105 / 255, 6), round(3 / 255, 6), 0.0]
    print("   en guerre : voile %s, alpha %.2f" % (veil(r3), r3.hover.alpha))
    assert veil(r3) == red, "FACTION_AT_WAR_COLOR : 105, 3, 0"
    assert abs(r3.hover.alpha - 0.85) < 1e-6,         "choisie ET en guerre : 0,85"
    lua.execute('ALL_FACTIONS[3].guerre = false')
    g.ForeverUI.ReputationLayout()

    # camelot's scroll bar, right of the list.
    #
    # camelot/reputationframe.xml: TOPLEFT on the ScrollBox TOPRIGHT (5, -2),
    # BOTTOMLEFT on its BOTTOMRIGHT (5, 4).
    bar = g.ForeverUIReputationScrollBar
    pbh = bar.points[1]
    pbb = bar.points[2]
    print("   barre : %s sur %s (%s, %s) et %s sur %s (%s, %s), %d de large" % (
        pbh[1], pbh[3], pbh[4], pbh[5], pbb[1], pbb[3], pbb[4], pbb[5],
        bar.width))
    assert (pbh[1], pbh[3], pbh[4], pbh[5]) == ("TOPLEFT", "TOPRIGHT", 5, -2)
    assert (pbb[1], pbb[3], pbb[4], pbb[5]) == ("BOTTOMLEFT", "BOTTOMRIGHT", 5, 4)
    assert pbh[2].name == "ForeverUIReputationList", "ancree sur la liste"
    assert bar.width == 8, "MinimalScrollBar fait 8 de large"

    # Everything fits: it hides, as the source does.
    print("   tout tient (%d factions) : barre visible=%s" % (
        g.GetNumFactions(), bar.shown))
    assert not bar.shown, "rien a faire defiler, rien a montrer"

    # It does not know the list: it gets three numbers.
    # The bench does not derive a height from two anchors, so set it.
    bar.track.SetHeight(bar.track, 300)
    bar.Configure(bar, 40, 10, 0)
    print("   40 lignes, 10 tiennent : visible=%s, curseur %s" % (
        bar.shown, bar.cursor.shown))
    assert bar.shown and bar.cursor.shown, "elle parait"
    pl2 = list_.points[len(list(list_.points.values()))]
    assert pl2[4] == -25 and list_.width == 363 and r1.width == 363 - 2 * 10, "avec la barre : les bornes de camelot"
    # Both thumb ends are the same piece, the second one flipped: the piece the source
    # names "bottom" is a gradient, not an end cap, and would fade the thumb into the
    # black track.
    parts = [t2 for t2 in bar.cursor.regions.values()
             if t2.texcoord is not None and t2.height == 8]
    assert len(parts) == 2, "un embout en haut, un en bas"
    topLeft = [round(v, 6) for v in parts[0].texcoord.values()]
    bottomLeft = [round(v, 6) for v in parts[1].texcoord.values()]
    print("   bouts du curseur : %s et %s" % (topLeft, bottomLeft))
    assert topLeft[0] == bottomLeft[0] and topLeft[1] == bottomLeft[1], "le meme morceau"
    assert topLeft[2] == bottomLeft[3] and topLeft[3] == bottomLeft[2], "le second est retourne"
    fh = g.ForeverUIReputationScrollBarUp
    fb = g.ForeverUIReputationScrollBarDown
    print("   fleches : %dx%d, haut=%s bas=%s" % (
        fh.width, fh.height, fh.points[1][1], fb.points[1][1]))
    assert fh.width == 17 and fh.height == 11, "17 x 11, elles debordent la barre"
    assert fh.points[1][1] == "TOP" and fb.points[1][1] == "BOTTOM"

    # The down arrow scrolls one step and returns the new offset.
    lua.execute("ForeverUIReputationScrollBar.onScroll = "
                "function(n) TEST_OFFSET = n end")
    fb.scripts.OnClick(fb)
    print("   clic sur la fleche du bas : decalage=%s" % lua.eval("TEST_OFFSET"))
    assert lua.eval("TEST_OFFSET") == 1, "un cran vers le bas"
    fh.scripts.OnClick(fh)
    assert lua.eval("TEST_OFFSET") == 0, "et un cran vers le haut"

    # At the end it stops: it clamps itself.
    bar.MoveTo(bar, 999)
    print("   au bout : decalage=%d (maximum 30)" % bar.offset)
    assert bar.offset == 30, "40 lignes moins les 10 qui tiennent"
    g.ForeverUI.ReputationLayout()

    # Right pane: details of the selected faction.
    detail = g.ReputationDetailFrame
    pd = detail.points[1]
    print("   detail : %s sur %s (%s, %s), titre=\"%s\" sous-titre=\"%s\"" % (
        pd[1], pd[2].name, pd[4], pd[5], detail.title.text, detail.subtitle.text))
    assert pd[2].name == "ForeverUICharacterRightPane",         "le cadre du client devient notre volet droit"
    print("   fond de fenetre : %s" % detail.backdrop)
    assert detail.backdrop is None,         "le <Backdrop> de 3.3.5 n est pas une region : SetBackdrop(nil) seul l enleve"
    assert (pd[4], pd[5]) == (16, -14),         "CharacterFrameSidePaneTemplate : TOPLEFT (16, -14)"
    assert detail.title.text == r3.name.text, "le titre est la faction choisie"
    assert detail.title.width == 195 and detail.title.justify == "CENTER",         "Title : large de 195, centre"
    assert detail.subtitle.justify == "CENTER", "Subtitle : centre lui aussi"
    assert detail.description.text and "Description de" in detail.description.text,         "la description vient du client, par ReputationFrame_Update"
    # White, and in a box: without a bottom anchor, a longer text has nowhere to wrap
    # and disappears.
    corners = [p[1] for p in detail.description.points.values()]
    print("   description : police=%s, ancrages=%s, repli=%s" % (
        detail.description.font, corners, detail.description.wordWrap))
    assert detail.description.font == "GameFontHighlight",         "GameFontNormal est DORE en 3.3.5 : le blanc est GameFontHighlight"
    assert "BOTTOMLEFT" in corners and "BOTTOMRIGHT" in corners,         "ses quatre bords, sinon le texte n a pas de boite"
    assert detail.description.wordWrap is True, "et il se replie dedans"

    print("   jauge du detail : %d x %d, remplissage %s" % (
        detail.gauge.width, detail.gauge.height, detail.gauge.fill.width))
    assert detail.gauge.width == 180 and detail.gauge.height == 29,         "StandingBar : 180 x 29"
    assert detail.gauge.fill.width == 180 * 0.25,         "la meme fraction que dans la liste, sur 180"

    cells = [g[n] for n in ("ReputationDetailAtWarCheckBox",
                            "ReputationDetailInactiveCheckBox",
                            "ReputationDetailMainScreenCheckBox")]
    pc = cells[0].points[1]
    print("   cases : %d x %d, la premiere %s sur %s (%s, %s), visibles=%s" % (
        cells[0].width, cells[0].height, pc[1], pc[3], pc[4], pc[5],
        [c.shown for c in cells]))
    assert all(c.width == 26 and c.height == 26 for c in cells), "26 x 26"
    assert (pc[1], pc[3], pc[4]) == ("TOPLEFT", "BOTTOMLEFT", -4),         "la premiere se pose depuis le bas du volet, x = -4"
    assert cells[1].points[1][2].name == cells[0].name,         "les suivantes s empilent sous elle"
    assert cells[1].points[1][5] == -2, "BOTTOMLEFT (0, -2)"
    assert all(c.shown for c in cells), "les trois paraissent pour une faction"

    # The swords belong to At War only: the other two boxes use checkmark-minimal, as
    # the source declares.
    print("   coches : guerre=%s | inactive=%s | barre=%s" % (
        cells[0].foreverCheck.texture, cells[1].foreverCheck.texture,
        cells[2].foreverCheck.texture))
    assert "SwordCheck" in (cells[0].foreverCheck.texture or ""),         "At War garde ses deux epees"
    for c in (cells[1], cells[2]):
        assert "SwordCheck" not in (c.foreverCheck.texture or ""),         "Move to Inactive et Show as Experience Bar prennent une coche"
        assert c.foreverCheck.points[1][1] == "CENTER",         "checkmark-minimal se centre sur la case"
    assert cells[0].foreverCheck.width == 32,         "la coche de guerre fait 32, posee a (3, -5)"

    # Nothing selected: the pane is empty.
    g.ForeverUI.ReputationSelect(None)
    print("   rien de choisi : titre=\"%s\", jauge=%s, cases=%s" % (
        detail.title.text, detail.gauge.shown, [c.shown for c in cells]))
    assert detail.title.text == "" and detail.description.text == "",         "sans faction choisie, le volet droit est vide"
    assert not detail.gauge.shown and not detail.separator.shown,         "ni jauge ni separateur"
    assert not any(c.shown for c in cells), "ni les trois options"

    # Checking "Move to Inactive" must not deselect.
    #
    # SetFactionInactive moves the faction: the client renumbers, and a saved index
    # would point to another row. The name does not change.
    g.ForeverUI.ReputationSelect("Darnassus")
    assert detail.title.text == "Darnassus"
    lua.execute("""
        -- le client range Darnassus ailleurs : tout se renumerote
        local keep = table.remove(ALL_FACTIONS, 3)
        table.insert(ALL_FACTIONS, keep)
    """)
    g.ReputationFrame_Update()
    print("   apres renumerotation : titre=\"%s\", indice du client=%d" % (
        detail.title.text, g.GetSelectedFaction()))
    assert detail.title.text == "Darnassus",         "le detail suit le NOM, pas l indice"
    assert g.GetFactionInfo(g.GetSelectedFaction())[0] == "Darnassus",         "et l indice du client est repose sur la bonne faction"
    lua.execute("""
        local keep = table.remove(ALL_FACTIONS)
        table.insert(ALL_FACTIONS, 3, keep)
    """)
    g.ForeverUI.ReputationSelect("Darnassus")

    # The selection is kept by name: collapsing renumbers the factions, an index
    # would follow the wrong row.
    selected = r3.name.text
    r2.scripts.OnClick(r2)                  # collapse Alliance
    g.ForeverUI.ReputationLayout()
    r2.scripts.OnClick(r2)                  # and expand it again
    g.ForeverUI.ReputationLayout()
    marked = [l.name.text for l in ranks.values() if l.shown and l.hover.alpha > 0.15]
    print("   apres un repli et un depli : marquee = %s (choisie %s)" % (
        marked, selected))
    assert marked == [selected], "la marque reste sur la meme faction"

    # Skills tab: the same screen as reputation, in blue.
    g.CharacterFrame_ShowSubFrame("SkillFrame")
    g.ForeverUI.Panes.ShowGroup("SkillFrame")
    g.ForeverUI.CharacterApplyPanes(character)

    s1, s2 = g.ForeverUISkillRow1, g.ForeverUISkillRow2
    ps1 = s1.points[len(list(s1.points.values()))]
    print("   competences : en-tete h=%d (%s, %s) | entree h=%d, nom x=%s, barre %d" % (
        s1.height, ps1[4], ps1[5], s2.height, s2.name.points[1][4], s2.bar.width))
    assert s1.height == 26, "SkillsHeaderTemplate fait 26, pas 28 comme la reputation"
    assert s2.height == 30, "SkillsEntryTemplate"
    assert (ps1[4], ps1[5]) == (10, -10), "marge de 10 sur les deux axes"
    assert s2.name.points[1][4] == 2,         "SkillsEntryTemplate : LEFT x = 2, il n y a pas d AccountWideIcon"
    assert s2.bar.width == 160 and s2.bar.height == 29, "SkillsBarTemplate"
    assert s2.bar.points[1][4] == -3, "RIGHT x = -3"

    # The bar is blue from its sprite, not from a tint.
    print("   remplissage : %s, large de %s" % (
        s2.bar.fill.texture, s2.bar.fill.width))
    assert "statbarfillblue" in (s2.bar.fill.texture or ""),         "SetFillTextureByColorType(Blue) : le bleu vient du sprite"
    assert s2.bar.fill.width == 160 * 0.5, "150 sur 300"
    assert s2.bar.text.text == "150 / 300", "rang / maximum"

    # A bonus is written in parentheses, in green.
    s3 = g.ForeverUISkillRow3
    print("   avec bonus : \"%s\"" % s3.bar.text.text)
    assert "(+5)" in s3.bar.text.text, "rang (+bonus) / maximum"

    # Details: title, 180-wide gauge, description.
    sd = g.ForeverUISkillDetail
    print("   detail : titre=\"%s\", jauge %d, description=\"%s\"" % (
        sd.title.text, sd.gauge.width, sd.description.text))
    assert sd.title.text == "Epees",         "SelectFirstSkillIfNoneSelected : la premiere qui n est pas un en-tete"
    assert sd.gauge.width == 180, "RankBar : 180 x 29"
    assert "epees" in sd.description.text, "la description, 13e valeur de GetSkillLineInfo"

    # The whole client screen stays hidden, not only its rows. SkillFrame also
    # declares a sort button, a "collapse all", its expand tiles, two buttons and a
    # whole detail frame.
    for name in ("SkillSortButton", "SkillFrameCollapseAllButton",
                "SkillListScrollFrame", "SkillDetailStatusBar"):
        if g[name]:
            g[name].Show(g[name])
    g.SkillFrame_UpdateSkills()
    g.ForeverUI.SkillsLayout()
    remaining = [n for n in ("SkillSortButton", "SkillFrameCollapseAllButton",
                            "SkillListScrollFrame", "SkillDetailStatusBar",
                            "SkillRankFrame1", "SkillTypeLabel1")
                if g[n] and g[n].shown]
    print("   ecran du client : %d morceau(x) encore visible(s)" % len(remaining))
    assert remaining == [], "il en reste : %s" % remaining
    assert g.ForeverUISkillList.shown, "mais notre panneau, lui, demeure"
    assert g.ForeverUISkillRow1.shown, "et nos lignes avec"
    # everything fits: no bar, the list takes its place (right edge at -10)
    sl = g.ForeverUISkillList
    assert not g.ForeverUISkillsScrollBar.shown
    assert sl.points[len(list(sl.points.values()))][4] == -10 and sl.width == 378
    sb_ = g.ForeverUISkillsScrollBar
    sb_.Configure(sb_, 40, 10, 0)
    assert sb_.shown and sl.points[len(list(sl.points.values()))][4] == -25 and sl.width == 363
    g.ForeverUI.SkillsLayout()
    assert not sb_.shown and sl.width == 378

    # Collapsing a header shortens the list, as for reputation.
    before = [l.name.text for l in g.ForeverUI.SkillsTab.Rows.values() if l.shown]
    s1.scripts.OnClick(s1)
    after = [l.name.text for l in g.ForeverUI.SkillsTab.Rows.values() if l.shown]
    print("   repli d Armes : %s -> %s" % (before, after))
    assert after == ["Armes", "Professions", "Couture"], "ses deux competences s en vont"
    s1.scripts.OnClick(s1)

    # Clicking a skill selects it, and the details follow.
    s3 = g.ForeverUISkillRow3
    s3.scripts.OnClick(s3)
    print("   clic sur Haches : detail=\"%s\", survol %.2f" % (
        sd.title.text, s3.hover.alpha))
    assert sd.title.text == "Haches", "le detail suit le clic"
    assert abs(s3.hover.alpha - 0.20) < 1e-6, "et la ligne est marquee"

    # Pet tab: the preview on the left, and on the right the same layout as the
    # character stats.
    lua.execute("HAS_PET = true")
    g.CharacterFrame_ShowSubFrame("PetPaperDollFrame")
    g.ForeverUI.Panes.ShowGroup("PetPaperDollFrame")
    g.ForeverUI.CharacterApplyPanes(character)

    model = g.PetModelFrame
    pm = model.points[len(list(model.points.values()))]
    print("   familier : apercu visible=%s unite=%s, borne a %s" % (
        model.shown, model.unit, pm[2].name))
    assert model.shown and model.unit == "pet", "l apercu montre le familier"
    assert g.PetPaperDollFramePetFrame.shown,         "l apercu est PETIT-fils de l ecran : son porteur doit survivre au balayage"
    assert pm[2].name == "ForeverUIPetPane", "et remplit le volet gauche"

    # Rotation arrows, at the same place as the character's: centered on the top of
    # the pane, side by side.
    fg = g.PetModelFrameRotateLeftButton
    fd = g.PetModelFrameRotateRightButton
    pg = fg.points[len(list(fg.points.values()))]
    pd = fd.points[len(list(fd.points.values()))]
    cg = g.CharacterModelFrameRotateLeftButton
    pcg = cg.points[len(list(cg.points.values()))]
    print("   fleches : familier %s (%s, %s) | personnage %s (%s, %s)" % (
        pg[1], pg[4], pg[5], pcg[1], pcg[4], pcg[5]))
    assert (pg[1], pg[4], pg[5]) == (pcg[1], pcg[4], pcg[5]),         "les memes que celles du personnage, au pixel pres"
    assert pg[3] == "TOP" and pd[4] == -pg[4], "cote a cote, centrees sur le haut"
    assert fg.shown and fd.shown, "et visibles"

    pet = g.ForeverUIPetStats
    print("   niveau : \"%s\"" % pet.level.text)
    assert pet.level.text == "Level 78 Sanglier", "Niveau X <nom du familier>"

    categories = []
    rank = 1
    while g["ForeverUIPetCategory" + str(rank)] is not None:
        c2 = g["ForeverUIPetCategory" + str(rank)]
        if c2.shown:
            categories.append((c2.label.text, c2.width, c2.height))
        rank += 1
    print("   categories : %s" % categories)
    assert [n for n, _, _ in categories] == ["General", "Resistances"],         "deux categories, dans cet ordre"
    assert categories[0][2] == 34, "la meme hauteur d en-tete que les statistiques"
    assert categories[0][1] == (233 - 2 * 20) + 2 * 5,         "et le meme debord de 5 de chaque cote"

    rows = []
    rank = 1
    while g["ForeverUIPetStat" + str(rank)] is not None:
        l = g["ForeverUIPetStat" + str(rank)]
        if l.shown:
            rows.append((l.label.text, l.value.text))
        rank += 1
    print("   lignes : %s" % ", ".join("%s %s" % (a2, b2) for a2, b2 in rows))
    assert [a2 for a2, _ in rows[:5]] == ["Health:", "Armor:", "Damage:",
                                            "Attack Power:", "Critical Strike:"],         "les cinq lignes demandees, dans cet ordre"
    assert [b2 for _, b2 in rows[:5]] == ["5400", "3120", "45 - 62", "1480",
                                            "4.25%"],         "les valeurs viennent du client, mises en forme par lui"
    # "Attack Power", not "Power": ATTACK_POWER is "Power" here.
    assert rows[3][0] == "Attack Power:",         "ATTACK_POWER vaut \"Power\" : c est ATTACK_POWER_TOOLTIP qu il faut"
    assert len(rows) == 5, "les resistances ne sont plus des lignes de texte"

    # Resistances are icons, laid out horizontally: the client frames, reparented into
    # the right pane, already carry the school icon, the value and the tooltip.
    res = [g["PetMagicResFrame" + str(i)] for i in range(1, 6)]
    xs = []
    for frame in res:
        p = frame.points[len(list(frame.points.values()))]
        xs.append(round(p[4], 2))
    print("   resistances : %s | tailles %dx%d | parent=%s | valeurs %s" % (
        xs, res[0].width, res[0].height, res[0].parent._name,
        [g["PetMagicResText" + str(i)].text for i in range(1, 6)]))
    assert all(c.shown for c in res), "les cinq paraissent"
    assert res[0].width == 32 and res[0].height == 29,         "MagicResistanceFrameTemplate fait 32 x 29"
    assert res[0].parent._name == "ForeverUIPetStats",         "reparentes dans le volet droit, que le balayage ne touche pas"
    assert xs[0] == 20, "la premiere au bord des lignes"
    mismatches = [round(xs[i + 1] - xs[i], 2) for i in range(4)]
    assert len(set(mismatches)) == 1, "a pas egaux : %s" % mismatches
    assert round(xs[4] + 32, 2) == 20 + (233 - 2 * 20),         "et la derniere au bord oppose"
    ys = [frame.points[len(list(frame.points.values()))][5] for frame in res]
    assert len(set(ys)) == 1, "toutes sur la meme ligne : %s" % ys
    assert g.PetMagicResText1.text == 120,         "le premier cadre porte l ecole 6, l arcane"

    # Alternating background, like the character stats; the count restarts at each
    # category.
    DARK2 = "ui-character-info-itemlevel-bounce"
    r_dark = tuple(round(lua.eval('UIAtlas.data["%s"]' % DARK2)[i], 6) for i in (2, 3, 4, 5))
    def petStrip(rank):
        background = g["ForeverUIPetStat" + str(rank)].background
        tc = tuple(round(v, 6) for v in background.texcoord.values())
        return "sombre" if tc == r_dark else "clair"
    strips = [petStrip(i) for i in (1, 2, 3, 4, 5)]
    print("   fonds : %s" % " ".join(strips))
    assert strips == ["sombre", "clair", "sombre", "clair", "sombre"],         "la sombre en premier"

    # Without a pet, the screen is empty and the preview shows nothing.
    lua.execute("HAS_PET = false")
    g.ForeverUI.PetPreview()
    g.ForeverUI.PetDetail()
    print("   sans familier : apercu=%s, niveau=\"%s\"" % (
        model.shown, pet.level.text))
    assert not model.shown and pet.level.text == "",         "sans familier, rien a montrer"
    lua.execute("HAS_PET = true")
    g.ForeverUI.PetPreview()
    g.ForeverUI.PetDetail()

    # Currency tab. The same list template as reputation and skills (ScrollBox with
    # the same bounds, same header plate, same three-slice hover) but only two levels:
    # GetCurrencyListInfo only returns isHeader, with no notion of child.
    g.CharacterFrame_ShowSubFrame("TokenFrame")
    g.ForeverUI.Panes.ShowGroup("TokenFrame")
    g.ForeverUI.CharacterApplyPanes(character)

    list_ = g.ForeverUITokenList
    pl = list_.points[1]
    pl2 = list_.points[2]
    print("   monnaies : panneau (%s, %s) a (%s, %s)" % (
        pl[4], pl[5], pl2[4], pl2[5]))
    assert (pl[4], pl[5]) == (10, -40) and (pl2[4], pl2[5]) == (-10, 15),         "pas de barre : la liste va jusqu a la marge de droite"

    ranks = {}
    rank = 1
    while g["ForeverUITokenRow" + str(rank)] is not None:
        ranks[rank] = g["ForeverUITokenRow" + str(rank)]
        rank += 1
    placedCount = [(l.name.text, l.header, l.height) for l in ranks.values() if l.shown]
    print("   lignes : %s" % ", ".join(
        "%s%s(%d)" % (n, " [cat]" if e else "", h) for n, e, h in placedCount))
    assert [n for n, _, _ in placedCount] == ["Miscellaneous", "Arena Points",
                                         "Honor Points", "Emblem of Frost",
                                         "Player vs. Player"],         "la categorie PvP est repliee : son contenu ne se pose pas"
    assert placedCount[0][2] == 26 and placedCount[1][2] == 22,         "TokenHeaderTemplate 26, TokenEntryTemplate 22"

    # The two special icons, which the client names itself.
    r2, r3, r4 = ranks[2], ranks[3], ranks[4]
    print("   icones : arene=%s | honneur=%s (rogne %.5f) | ordinaire=%s" % (
        r2.icon.texture.split(chr(92))[-1], r3.icon.texture.split(chr(92))[-1],
        list(r3.icon.texcoord.values())[0], r4.icon.texture))
    assert "ArenaPoints" in r2.icon.texture, "typeSpecial 1 : les points d arene"
    assert "UI-PVP-Alliance" in r3.icon.texture, "typeSpecial 2 : la faction"
    assert abs(list(r3.icon.texcoord.values())[0] - 0.03125) < 1e-6,         "et son rognage"
    assert r4.icon.texture == "icone_embleme", "les autres prennent l icone rendue"

    # A currency at zero is written in gray, as the client does.
    print("   police : zero=%s | non nul=%s" % (r3.name.font, r4.name.font))
    assert r3.name.font == "GameFontDisable", "compte nul : GameFontDisable"
    assert r4.name.font == "GameFontHighlight", "sinon GameFontHighlight"
    print("   coche de suivi : %s" % [bool(ranks[i].checkMark.shown) for i in (2, 3, 4)])
    assert r4.checkMark.shown and not r2.checkMark.shown, "seule la monnaie suivie est cochee"

    # Expanding the PvP category lengthens the list.
    r5 = ranks[5]
    r5.scripts.OnClick(r5)
    placedCount = [l.name.text for l in ranks.values() if l.shown]
    print("   apres depli : %s" % ", ".join(placedCount))
    assert "Wintergrasp Mark" in placedCount, "son contenu arrive"

    # Clicking a currency selects it, and the right pane follows.
    td = g.ForeverUITokenDetail or g.TokenFramePopup
    r4.scripts.OnClick(r4)
    print("   clic : titre=\"%s\" sous-titre=\"%s\" survol=%.2f" % (
        td.title.text, td.subtitle.text, r4.hover.alpha))
    assert td.title.text == "Emblem of Frost", "le detail suit le clic"
    assert td.subtitle.text == "42", "sa quantite"
