    # The same alternating background: the two paperdollinfopart1c60 strips, dark
    # first.
    def titleStrip(rank):
        background = g["ForeverUITitleRow" + str(rank)].background
        if background is None or background.texcoord is None:
            return None
        tc = tuple(round(v, 6) for v in background.texcoord.values())
        for name, r in rects.items():
            if tc == r:
                return "sombre" if name == DARK else "clair"
        return "?"

    strips = [titleStrip(r) for r in range(1, 5)]
    print("   fond des titres : %s" % " ".join(str(b) for b in strips))
    assert strips == ["sombre", "clair", "sombre", "clair"],         "les memes bandes que les statistiques, la sombre en premier"

