    # Clicking Statistics: camelot's StatisticsFrame over the client's achievement statistics
    # (StatisticsTab.lua). Fake API: GetStatisticsCategoryList, GetCategoryInfo (name,
    # parent; -1 at top level), GetCategoryNumAchievements, GetAchievementInfo(category,
    # index), GetStatistic(id) -> value, skip.
    lua.execute("""
        STATS_CATEGORIES = { 130, 140, 141, 142 }
        STATS_CAT = { [130] = { "Character", -1 }, [140] = { "Wealth", 130 },
                      [141] = { "Combat", -1 }, [142] = { "Kills", -1 } }
        STATS_LIST = { [130] = { 349 }, [140] = { 328, 329, 330, 1299 }, [141] = { 1000 }, [142] = {} }
        STATS_NAME = { [349] = "Talent tree respecs", [328] = "Total gold acquired",
                      [329] = "Auctions posted", [330] = "Gold spent", [1299] = "Health potion used most",
                      [1000] = "Damage done" }
        STATS_GOLD = "12|TInterface" .. string.char(92) .. "MoneyFrame" .. string.char(92) .. "UI-GoldIcon:0:0:2:0|t"
        STATS_VALUE = { [349] = "3", [328] = STATS_GOLD, [329] = nil, [330] = "7",
                         [1299] = "Runic Healing Potion", [1000] = "42" }
        STATS_SKIP = { [330] = true }
        for k = 1, 40 do
            STATS_LIST[142][k] = 2000 + k
            STATS_NAME[2000 + k] = "Kill " .. k
            STATS_VALUE[2000 + k] = tostring(k)
        end
        function GetStatisticsCategoryList() return STATS_CATEGORIES end
        function GetCategoryInfo(id) local c = STATS_CAT[id] return c[1], c[2], 0 end
        function GetCategoryNumAchievements(id) return #(STATS_LIST[id] or {}), 0 end
        STATS_ORIGINAL = GetAchievementInfo
        function GetAchievementInfo(a, b)
            if b then return STATS_LIST[a][b] end
            if STATS_NAME[a] then return a, STATS_NAME[a] end
            return STATS_ORIGINAL(a)
        end
        function GetStatistic(id) return STATS_VALUE[id], STATS_SKIP[id] end
    """)
    stat.scripts.OnClick(stat)
    print("   clic statistiques : PvP visible=%s, volet droit=%s" % (
        g.PVPParentFrame.shown, right.shown))
    assert not g.PVPParentFrame.shown, "le PvP s en va"
    assert right.shown, "le volet droit reste"
    st = g.ForeverUI.StatisticsTab
    stf, stl = g.ForeverUIStatisticsFrame, g.ForeverUIStatisticsList
    # Values of anchor k of region r.
    def st_pt(r, k=1):
        return list(r.points[k].values())
    # The last anchor with this name (the fake client appends, the real one replaces).
    def st_anchor(r, name):
        pts_ = [list(v.values()) for v in r.points.values()]
        return [q for q in pts_ if q[0] == name][-1]
    # True if texture t shows the atlas entry name.
    def st_art(t, name):
        e = g.ForeverUI.AtlasEntry(name)
        return t.texture == e[1] and list(t.texcoord.values()) == [e[2], e[3], e[4], e[5]]
    st_rows = [st.Rows[k] for k in range(1, len(list(st.Rows.values())) + 1)]
    shownRows = [l for l in st_rows if l.shown]
    summary = [(l.kind, l.name.text, l.value.text) for l in shownRows]
    print("   statistiques : %d lignes montrees, %s" % (len(shownRows), summary[:6]))
    assert stf.shown and stf.parent._name == "ForeverUICharacterLeftPane"
    # The list: (10, -40) and (-25, 15) from the host (camelot ScrollBox).
    assert st_pt(stl, 1)[2:] == ["TOPLEFT", 10, -40]
    # Hierarchy: category, its statistics, then its subcategories; "skip" entries omitted;
    # client values as is (a name, an amount with coins); "--" when there is no value.
    assert summary[:9] == [("header", "Character", ""), ("stat", "Talent tree respecs", "3"),
                          ("sub", "Wealth", ""), ("stat", "Total gold acquired", g.STATS_GOLD),
                          ("stat", "Auctions posted", "--"), ("stat", "Health potion used most", "Runic Healing Potion"),
                          ("header", "Combat", ""), ("stat", "Damage done", "42"), ("header", "Kills", "")], summary[:9]
    # Value column: 50, or its content width, up to half the row.
    potion = shownRows[5]
    assert potion.value.width == len("Runic Healing Potion") * 6 and potion.value.width <= potion.width / 2, (potion.value.width, potion.width)
    assert shownRows[3].value.width == int(shownRows[3].width // 2), "le montant avec ses pieces, plafonne"
    assert shownRows[1].value.width == 50
    l1, l2, l3, l4 = shownRows[0], shownRows[1], shownRows[2], shownRows[3]
    # Indent 20 per level, margins 10, gap 3; heights 26 / 24 / 22.
    assert st_pt(l1)[2:] == ["TOPLEFT", 10, -10] and l1.height == 26
    assert st_pt(l2)[2:] == ["TOPLEFT", 30, -(10 + 26 + 3)] and l2.height == 24
    assert st_pt(l3)[2:] == ["TOPLEFT", 30, -(10 + 26 + 3 + 24 + 3)] and l3.height == 22
    assert st_pt(l4)[2:4] == ["TOPLEFT", 50]
    # Header: plate, name at 10, minus at (-8, -1); entry: value at -12.
    assert l1.plate[1].shown and l1.arrow.shown and st_art(l1.arrow, "common-button-list-minus")
    assert st_pt(l1.arrow)[2:] == ["RIGHT", -8, -1] and not l2.plate[1].shown
    assert st_pt(l2.value)[2:] == ["RIGHT", -12, 0] and l2.value.width == 50
    # Subheader: its open button on the left, name at 2 + 20 + 4.
    assert l3.button.shown and st_art(l3.button._normal, "campaign_headericon_open")
    assert st_art(l3.button._pushed, "campaign_headericon_openpressed")
    assert st_pt(l3.button)[2:] == ["LEFT", 2, 0] and (l3.button.width, l3.button.height) == (20, 20)
    assert st_pt(l3.name)[2:] == ["LEFT", 26, 0]
    # Scroll bar: 40 more statistics, the list scrolls.
    assert stl.bar.shown, "la barre, puisque tout ne tient pas"
    before = shownRows[0].name.text
    stl.scripts.OnMouseWheel(stl, -1)
    after = [l for l in st_rows if l.shown][0].name.text
    assert before == "Character" and after == "Talent tree respecs", (before, after)
    stl.scripts.OnMouseWheel(stl, 1)
    # Collapse the subcategory, then the category.
    l3.scripts.OnClick(l3)
    summary = [(l.kind, l.name.text) for l in st_rows if l.shown]
    assert summary[:4] == [("header", "Character"), ("stat", "Talent tree respecs"),
                          ("sub", "Wealth"), ("header", "Combat")], summary[:4]
    assert st_art(l3.button._normal, "campaign_headericon_closed")
    l1.scripts.OnClick(l1)
    summary = [(l.kind, l.name.text) for l in st_rows if l.shown]
    assert summary[:3] == [("header", "Character"), ("header", "Combat"), ("stat", "Damage done")], summary[:3]
    assert st_art(l1.arrow, "common-button-list-plus")
    # CRITERIA_UPDATE: values refresh, the collapsed state stays.
    lua.execute("STATS_VALUE[1000] = '43'")
    stf.scripts.OnEvent(stf, "CRITERIA_UPDATE")
    summary = [(l.kind, l.name.text, l.value.text) for l in st_rows if l.shown]
    assert summary[:3] == [("header", "Character", ""), ("header", "Combat", ""), ("stat", "Damage done", "43")], summary[:3]
    # Hovering an entry: alpha 0.10; never on a header.
    ent = [l for l in st_rows if l.shown][2]
    ent.mouse = True
    ent.scripts.OnEnter(ent)
    assert ent.hover.alpha == 0.10
    ent.mouse = False
    ent.scripts.OnLeave(ent)
    assert ent.hover.alpha == 0
    # Pressed: the content shifts by (1, -1).
    ent.scripts.OnMouseDown(ent)
    assert st_anchor(ent.content, "TOPLEFT")[2:] == ["TOPLEFT", 1, -1]
    ent.scripts.OnMouseUp(ent)
    assert st_anchor(ent.content, "TOPLEFT")[2:] == ["TOPLEFT", 0, 0]
    # Events are registered only while the tab is shown.
    assert "CRITERIA_UPDATE" in stf.events
    stf.scripts.OnHide(stf)
    assert "CRITERIA_UPDATE" not in stf.events
    stf.scripts.OnShow(stf)
    lua.execute("GetAchievementInfo = STATS_ORIGINAL")

    # Back to the character sheet through a client tab: our pages hide.
