    # Reported sequence, from scratch: create AAA, rename it AAB, create AZE, delete AAB. The
    # list must follow at each step, not show the previous state.
    lua.execute('SETS = {} publishSets()')
    lua.execute('ForeverUIDB.setOrder = {}')
    lua.execute('GearManagerDialog_Update()')
    g.ForeverUI.EquipmentSetsLayout()

    def visibleNow():
        return [b.name for b in g.GearManagerDialog.buttons.values() if b.shown]

    # The client publishes, fires EQUIPMENT_SETS_CHANGED, then one frame passes.
    def afterChange():
        lua.execute("publishSets()")
        att2 = g.ForeverUIEquipmentEdit
        att2.scripts.OnEvent(att2, "EQUIPMENT_SETS_CHANGED")
        nextFrame()

    lua.execute('SaveEquipmentSet("AAA", 1)')
    afterChange()
    print("   sequence : creer AAA -> %s" % visibleNow())
    assert visibleNow() == ["AAA"], "AAA doit s afficher"

    lua.execute('SaveEquipmentSet("AAB", 1) DeleteEquipmentSet("AAA")')
    lua.execute('ForeverUIDB.setOrder = { "AAB" }')
    afterChange()
    print("   sequence : AAA renomme en AAB -> %s" % visibleNow())
    assert visibleNow() == ["AAB"], "le renomme doit rester visible"

    lua.execute('SaveEquipmentSet("AZE", 2)')
    afterChange()
    print("   sequence : creer AZE -> %s" % visibleNow())
    assert visibleNow() == ["AAB", "AZE"], "les deux doivent etre la"

    lua.execute('DeleteEquipmentSet("AAB")')
    afterChange()
    print("   sequence : supprimer AAB -> %s" % visibleNow())
    assert visibleNow() == ["AZE"], "AZE reste, seul"

    # The client publishes after everyone: the event arrives before the client rebuilds its
    # list, the one-frame catch-up finds nothing, and nothing else is signaled. Only the
    # pane's periodic check can repair it.
    lua.execute('SETS = {} publishSets()')
    lua.execute('ForeverUIDB.setOrder = {}')
    lua.execute('SaveEquipmentSet("AAA", 1)')
    afterChange()
    assert visibleNow() == ["AAA"], "point de depart : AAA est la"

    lua.execute('SaveEquipmentSet("AAB", 1) DeleteEquipmentSet("AAA")')
    lua.execute('ForeverUIDB.setOrder = { "AAB" }')
