    att3.scripts.OnEvent(att3, "EQUIPMENT_SETS_CHANGED")   # too early
    nextFrame()                                        # finds nothing yet
    print("   publication tardive : au signal -> %s" % visibleNow())
    assert "AAB" not in visibleNow(),         "le client n a encore rien publie : la liste est en retard"

    lua.execute("publishSets()")   # the client publishes without any event
    pan = g.ForeverUIEquipmentPane
    pan.scripts.OnUpdate(pan, 0.25)
