    assert installed == [1], "un ensemble publie ne se pose qu une fois"
    assert visibleNow() == ["aab"], "et sa carte doit etre visible"
    assert list(g.ForeverUIDB.setOrder.values()) == ["aab"],         "l ordre retenu se nettoie des doublons et des noms effaces"

