    assert not plus.shown and not minus.shown, "masques tant que la souris n est pas la"
    # Bench quirk: Minimap.lua hooks OnEnter (HookScript) so it does not overwrite the
    # client's script. The real client stores the hook as the script when there is none;
    # the bench keeps it apart in hooks, so call it there.
    map_.hooks["OnEnter"](map_)
    print("   apres survol de la carte : + visible=%s, - visible=%s" % (plus.shown, minus.shown))
    assert plus.shown and minus.shown, "MinimapMixin:OnEnter les montre"
    lua.execute("Minimap.mouse = false MinimapZoomIn.mouse = false MinimapZoomOut.mouse = false ForeverUIMinimapZoomHitArea.mouse = false")
    map_.hooks["OnLeave"](map_)
    assert not plus.shown, "et OnLeave les reprend quand la souris n est nulle part"
    # Mouse wheel: same effect as the buttons, up "+", down "-", nothing on a button
    # disabled at the end of its range.
    lua.execute("""
        ZOOM_CLICKS = ""
        MinimapZoomIn:SetScript("OnClick", function() ZOOM_CLICKS = ZOOM_CLICKS .. "+" end)
        MinimapZoomOut:SetScript("OnClick", function() ZOOM_CLICKS = ZOOM_CLICKS .. "-" end)
    """)
    assert map_.wheelEnabled, "la carte prend la molette"
    map_.scripts.OnMouseWheel(map_, 1)
    map_.scripts.OnMouseWheel(map_, -1)
    lua.execute("MinimapZoomIn:Disable()")
    map_.scripts.OnMouseWheel(map_, 1)
    lua.execute("MinimapZoomIn:Enable()")
    print("   molette : %s" % g.ZOOM_CLICKS)
