    lua.execute("""
        function NEXT_FRAME()
            local e = ForeverUI.QuestLog.flagClearer
            if e and e:IsShown() then e.scripts.OnUpdate(e, 0.01) end
            STATE.time = STATE.time + 1
        end
    """)
    # L: QuestLogFrame stays hidden, the map opens with the pane; L again closes it, even if
