    assert list(close.points[1].values())[1]._name == "ForeverUIWorldMapMaximized" and abs(close.GetEffectiveScale(close) - 0.64) < 1e-9
    assert pr[0] == "RIGHT" and pr[1]._name == "WorldMapFrameCloseButton" and abs(shrink.GetEffectiveScale(shrink) - 0.64) < 1e-9
    assert shrink.GetNormalTexture(shrink).texcoord[1] == g.UIAtlas.data["redbutton-condense"][2], "RedButton-Condense"
    assert (g.WorldMapDetailTile12.width, g.WorldMapDetailTile12.height) == (234, 156), "les tuiles rognees a la carte"
    # A WotLK view re-sets the map and the list: we re-apply after it.
