    assert worldMap.shown and g.WORLDMAP_SETTINGS.size == g.WORLDMAP_WINDOWED_SIZE and g.ForeverUIQuestLogPanel.shown
    lua.execute("NEXT_FRAME() ToggleFrame(QuestLogFrame)")
    assert not worldMap.shown and not g.QuestLogFrame.shown, "un second appui ferme"

    # Map zoom: the wheel scales the map toward the cursor, dragging moves it, tiles are
    # cropped to the view, POIs out of view are hidden, the arrow is re-placed x zoom; zoom
    # resets to 1 on map change and on close.
    lua.execute("NEXT_FRAME() ToggleFrame(QuestLogFrame)")
    Z = g.ForeverUI.WorldMap.zoom
    can, det, btn = g.ForeverUIWorldMapCanvas, g.WorldMapDetailFrame, g.WorldMapButton
    size = g.WORLDMAP_SETTINGS.size
    assert worldMap.shown and Z.z == 1 and btn.wheelEnabled
    # On-screen canvas: 697 x 465 centered at (500, 400); cursor at the center.
    lua.execute("""
        local c = ForeverUIWorldMapCanvas
        local e = c:GetEffectiveScale()
        c._cx, c._cy = 500 / e, 400 / e
        c._left, c._right = (500 - 697 / 2 * e) / e, (500 + 697 / 2 * e) / e
        c._bottom, c._top = (400 - 465 / 2 * e) / e, (400 + 465 / 2 * e) / e
        MOUSE_X, MOUSE_Y = 500, 400
    """)
    btn.scripts.OnMouseWheel(btn, 1)
    print("   zoom : %.4f, centre (%.3f, %.3f), echelle de la carte %.4f (%.4f x 1,25)" % (Z.z, Z.cx, Z.cy, det.scale, size))
    assert abs(Z.z - 1.25) < 1e-9 and abs(det.scale - size * 1.25) < 1e-9 and abs(btn.scale - size * 1.25) < 1e-9
    assert abs(g.WorldMapPOIFrame.scale - 1.25) < 1e-9 and g.WorldMapBlobFrame.alpha == 0
    assert abs(Z.cx - 0.5) < 1e-9 and abs(Z.cy - 0.5) < 1e-9, "curseur au centre : le centre reste"
    pd = list(det.points[1].values())
    assert pd[0] == "CENTER" and pd[1]._name == "ForeverUIWorldMapCanvas"
    x0, y0, x1, y1 = Z.view()
    t1 = g.WorldMapDetailTile1
    pt1 = list(t1.points[1].values())
    print("   vue (%.1f, %.1f) -> (%.1f, %.1f) ; tuile 1 a (%.1f, %.1f) %.1f x %.1f" % (x0, y0, x1, y1, pt1[3], -pt1[4], t1.width, t1.height))
    assert abs(pt1[3] - x0) < 1e-6 and abs(-pt1[4] - y0) < 1e-6 and abs(t1.width - (256 - x0)) < 1e-6, "la tuile 1 commence au bord de la vue"
    assert abs(list(t1.texcoord.values())[0] - x0 / 256) < 1e-9
    hr = list(btn.hitRect.values())
    assert abs(hr[0] - x0) < 1e-6 and abs(hr[1] - (1002 - x1)) < 1e-6, "la surface cliquable est bornee a la vue"
    # One more step, cursor offset by (100, 50): the point under the cursor stays there.
    lua.execute("MOUSE_X, MOUSE_Y = 600, 450")
    de = det.GetEffectiveScale(det)
    fx, fy = Z.cx + 100 / (1002 * de), Z.cy - 50 / (668 * de)
    btn.scripts.OnMouseWheel(btn, 1)
    de2 = det.GetEffectiveScale(det)
    fx2, fy2 = Z.cx + 100 / (1002 * de2), Z.cy - 50 / (668 * de2)
    print("   sous le curseur : (%.4f, %.4f) avant, (%.4f, %.4f) apres" % (fx, fy, fx2, fy2))
    assert abs(fx - fx2) < 1e-9 and abs(fy - fy2) < 1e-9
    # Player arrow, x zoom.
    lua.execute("POSITION.x, POSITION.y = 0.5, 0.5")
    btn.hooks["OnUpdate"](btn)
    fl = list(g.ARROW.pos.values())
    print("   fleche : %s" % fl)
    assert abs(fl[3] - 0.5 * 1002 * size * Z.z) < 1e-6 and abs(fl[4] + 0.5 * 668 * size * Z.z) < 1e-6
    # A POI out of view is hidden, and comes back when it re-enters.
    lua.execute("""
        local j = WorldMapPlayer
        j:Show()
        j:EnableMouse(true)
        local e = j:GetEffectiveScale()
        j._cx, j._cy = 50 / e, 400 / e
        ForeverUI.WorldMap.zoom.watcher.scripts.OnUpdate(ForeverUI.WorldMap.zoom.watcher, 0.01)
    """)
    assert g.WorldMapPlayer.alpha == 0 and g.WorldMapPlayer.mouseEnabled is False, "hors de la vue, sans souris"
    lua.execute("""
        local j = WorldMapPlayer
        local e = j:GetEffectiveScale()
        j._cx, j._cy = 500 / e, 400 / e
        ForeverUI.WorldMap.zoom.watcher.scripts.OnUpdate(ForeverUI.WorldMap.zoom.watcher, 0.01)
    """)
    assert g.WorldMapPlayer.alpha == 1 and g.WorldMapPlayer.mouseEnabled, "revenu dans la vue, sa souris rendue"
    # Drag: left button down, 60 px right: the map follows and WorldMapButton releases the
    # mouse; on release it takes it back.
    watcherZ = Z.watcher
    cx0 = Z.cx
    lua.execute("MOUSE_X, MOUSE_Y = 500, 400 MOUSE_BUTTONS.LeftButton = true")
    btn.hooks["OnMouseDown"](btn, "LeftButton")
    lua.execute("MOUSE_X = 560")
    watcherZ.scripts.OnUpdate(watcherZ, 0.01)
    de = det.GetEffectiveScale(det)
    print("   glisser de 60 : centre %.4f -> %.4f, souris de la carte %s" % (cx0, Z.cx, btn.mouseEnabled))
    assert Z.dragging and btn.mouseEnabled is False and abs(Z.cx - (cx0 - 60 / (1002 * de))) < 1e-9
    lua.execute("MOUSE_BUTTONS.LeftButton = nil")
    watcherZ.scripts.OnUpdate(watcherZ, 0.01)
    assert not Z.dragging and btn.mouseEnabled, "le relachement rend la souris a la carte"
    # Back to 1 with the wheel: everything is restored.
    for _ in range(3):
        btn.scripts.OnMouseWheel(btn, -1)
    t2 = g.WorldMapDetailTile2
    pt2 = list(t2.points[1].values())
    print("   retour a 1 : echelle %.4f, tuile 2 sur %s, tuile 4 %s x %s, marges %s" % (
        det.scale, pt2[1]._name, g.WorldMapDetailTile4.width, g.WorldMapDetailTile4.height, list(btn.hitRect.values())))
    assert Z.z == 1 and not Z.active and abs(det.scale - size) < 1e-9 and g.WorldMapPOIFrame.scale == 1
    assert pt2[1]._name == "WorldMapDetailTile1" and pt2[2] == "TOPRIGHT", "les tuiles reprennent leur chaine"
    assert g.WorldMapDetailTile4.width == 234 and g.WorldMapBlobFrame.alpha == 1 and list(btn.hitRect.values()) == [0, 0, 0, 0]
    assert list(det.points[1].values())[0] == "TOPLEFT", "la carte reprend son ancre de la petite fenetre"
    # A map change resets to 1.
    btn.scripts.OnMouseWheel(btn, 1)
    assert Z.active
    lua.execute("MAP.id = (MAP.id or 0) + 1")
    watcherZ.scripts.OnUpdate(watcherZ, 0.01)
    assert Z.z == 1 and not Z.active, "nouvelle carte : zoom a 1"
    # Closing the map resets to 1.
    btn.scripts.OnMouseWheel(btn, 1)
    lua.execute("WorldMapFrame:Hide()")
    assert Z.z == 1 and not Z.active
    print("   zoom ramene a 1 : changement de carte, fermeture")

    # ------------------------------------------------------------------
    # QUEST TRACKER (docs/SUIVI_DES_QUETES.md)
    # ------------------------------------------------------------------
    print("\n--- suivi de quetes ---")
    same = lua.eval("function(a, b) return rawequal(a, b) end")
    handlers = list(g.WATCHFRAME_OBJECTIVEHANDLERS.values())
    ot = g.ForeverUI.ObjectiveTracker
    print("   gestionnaires : %d" % len(handlers))
    assert len(handlers) == 2 and same(handlers[0], ot.displayQuests) and same(handlers[1], ot.achievementHandler), \
        "les deux modules de camelot remplacent les trois gestionnaires de WotLK"
    # WotLK's API stays open to addons: an added handler runs after ours.
    lua.execute("ADDON_CALLED = nil WatchFrame_AddObjectiveHandler(function(l, o) ADDON_CALLED = o return 0, 0, 0 end)")

