    assert [c.name.text for c in cells] == ["Frostbolt", "Frost Armor", "Ice Shards"], "un seul Frostbolt : son rang le plus haut"
    assert cells[0].button.attributes.spell == "Frostbolt(Rank 3)" and cells[0].button.attributes.type1 == "spell"
