    lua.execute("""
        SPELL_LINKS = { spell8 = 12043 }
        ORIG_SPELL_LINK = GetSpellLink
        function GetSpellLink(slot, book)
            local id = SPELL_LINKS[book .. slot]
            if id then return "|cff71d5ff|Hspell:" .. id .. "|h[x]|h|r" end
            return ORIG_SPELL_LINK(slot, book)
        end
        SPELL_BOOK.spell[8] = { "Presence of Mind", "", false, "ic:presence" }
        TABS[2][4] = TABS[2][4] + 1
        TAKEN = {}
        function NODE(name)
            for _, b in pairs(ForeverUI.Talents.tree.nodes) do
                if b:IsShown() and b.talent and b.talent.name == name then return b end
            end
        end
        function DRAG(name) local b = NODE(name) b.scripts.OnDragStart(b) end
        DRAG("Presence of Mind")
    """)
    assert len(list(g.TAKEN.values())) == 0, "pas encore appris : rien"
