    # Minimize button at the top of the column
    pm = pts(g.ChatFrame1ButtonFrameMinimizeButton)[-1]
    assert (pm[0], pm[2], pm[3], pm[4]) == ("TOP", "TOP", 0, 4)
    # Column on the background (Camelot's FCF_SetButtonSide)
    lua.execute("FCF_SetButtonSide(ChatFrame1, 'left')")
    pc = pts(c1.buttonFrame)
    print("   colonne a gauche : %s" % [(p[0], p[1]._name, p[2], p[3], p[4]) for p in pc])
    assert [(p[0], p[1]._name, p[2], p[3], p[4]) for p in pc] == [
        ("TOPRIGHT", "ChatFrame1Background", "TOPLEFT", -3, -3), ("BOTTOMRIGHT", "ChatFrame1Background", "BOTTOMLEFT", -3, 6)]
    # Menu button at the bottom of the column; the Camelot friends button
    pmenu = pts(g.ChatFrameMenuButton)[-1]
    assert (pmenu[0], pmenu[1]._name, pmenu[2], pmenu[3], pmenu[4]) == ("BOTTOM", "ChatFrame1ButtonFrame", "BOTTOM", 0, 0)
    fa = g.FriendsMicroButton
    pa = pts(fa)[-1]
