    assert fa._normal.texture == g.ForeverUI.AtlasEntry("quickjoin-button-friendslist-up")[1]
    assert fa._pushed.texture == g.ForeverUI.AtlasEntry("quickjoin-button-friendslist-down")[1]
    assert (pa[0], pa[1]._name, pa[2], pa[3], pa[4]) == ("BOTTOMLEFT", "ChatFrame1ButtonFrame", "TOPLEFT", 0, 27)
    lua.execute("FCF_SetButtonSide(ChatFrame1, 'right')")
    pc = pts(c1.buttonFrame)
    pa = pts(fa)[-1]
    assert (pc[0][0], pc[0][2], pc[0][3]) == ("TOPLEFT", "TOPRIGHT", 3) and (pa[0], pa[2]) == ("BOTTOMRIGHT", "TOPRIGHT")
    lua.execute("FCF_SetButtonSide(ChatFrame1, 'left')")
    # Scroll bar and return button, placed as in Camelot
    d1 = C.windows[c1]
    pb = pts(d1.bar)
    pr = pts(d1.backButton)[-1]
    assert (pb[0][0], pb[0][2], pb[0][3], pb[0][4]) == ("TOPLEFT", "TOPRIGHT", 0, 0)
    assert (pb[1][0], pb[1][2], pb[1][4]) == ("BOTTOMLEFT", "TOPLEFT", 2) and lua.eval("rawequal")(pb[1][1], d1.backButton)
    assert (pr[0], pr[1]._name, pr[2], pr[3], pr[4]) == ("BOTTOMRIGHT", "ChatFrame1ResizeButton", "TOPRIGHT", -2, -2)
    assert d1.backButton.width == 17 and d1.backButton.height == 15
    assert d1.backButton._normal.texture == g.ForeverUI.AtlasEntry("minimal-scrollbar-arrow-returntobottom-c60")[1]
    # Scrolling: 30 messages, 7 fit (120 / (14 + 2)); at the bottom,
