    lua.execute("ChatFrame1.messages = 30; ChatFrame2.messages = 30")
    # Advances the chat engine by t seconds
    def engine(t):
        lua.execute("local m = ForeverUI.Chat.engine; m.scripts.OnUpdate(m, %s)" % t)
    engine(0.01)
    print("   defilement : barre %s, total %s, visibles %s, rang %s" % (d1.bar.shown, d1.bar.total, d1.bar.visibleCount, d1.bar.offset))
    size = lua.execute("local _, t = ChatFrame1:GetFont(); return t or 14")
    vis = int(120 // (size + 2))
    assert d1.bar.shown and (d1.bar.total, d1.bar.visibleCount, d1.bar.offset) == (30, vis, 30 - vis)
    # Dragging the scroll bar: SetScrollOffset when the client has it...
    lua.execute("local d = ForeverUI.Chat.windows[ChatFrame1]; d.bar.onScroll(10)")
    assert c1.scroll == 30 - vis - 10 and d1.bar.offset == 10
    # ... otherwise ScrollUp / ScrollDown
    d2 = C.windows[c2]
    lua.execute("local d = ForeverUI.Chat.windows[ChatFrame2]; d.bar.onScroll(20)")
    assert c2.scroll == 30 - vis - 20, c2.scroll
    # Not at the bottom: the return button flashes and the scroll bar lights up
