    assert d1.bar.alpha == 0 and d1.backButton.alpha == 0
    lua.execute("FCF_FadeInChatFrame(ChatFrame1)")
    engine(0.2)
    print("   allume : barre %.2f, retour %.2f" % (d1.bar.alpha, d1.backButton.alpha))
    assert abs(d1.bar.alpha - 0.6) < 1e-9 and abs(d1.backButton.alpha - 0.65) < 1e-9
    # Mouse over the scroll bar: the chat does not fade out
