    lua.execute("FCF_FadeOutChatFrame(ChatFrame1)")
    engine(0.01)
    print("   souris sur la barre : %s, allume %s" % (list(g.FADED.values()), d1.isLit))
    assert list(g.FADED.values()) == ["out ChatFrame1"] and d1.isLit
    lua.execute("MOUSE_OVER = {}")
    engine(1.1)
    assert not d1.isLit
    lua.execute("FCF_FadeInChatFrame(ChatFrame1)")


    # Idle: tabs, column buttons and edit box fade with the chat (their regions;
