    tab1 = [g.ChatFrame1TabLeft, g.ChatFrame1TabText]
    input1 = [g.ChatFrame1EditBoxLeft, g.ChatFrame1EditBoxMid, g.ChatFrame1EditBoxHeader]
    buttons1 = [g.ChatFrame1ButtonFrameMinimizeButton, g.ChatFrameMenuButton, g.FriendsMicroButton]
    overhang = [r for r in lua.eval("{ GENERAL_CHAT_DOCK.overflowButton:GetRegions() }").values()
              if not lua.eval("rawequal")(r, g.GENERAL_CHAT_DOCK.overflowButton._highlight)]
    engine(0.2)
    assert all(abs(o.alpha - 1) < 1e-9 for o in tab1 + input1 + buttons1 + overhang)
    lua.execute("FCF_FadeOutChatFrame(ChatFrame1)")
    engine(1.0)
    print("   au repos, a 1 s : onglet %.2f, saisie %.2f, amis %.2f" % (tab1[0].alpha, input1[0].alpha, g.FriendsMicroButton.alpha))
    assert abs(tab1[0].alpha - 0.5) < 1e-9
    engine(1.1)
    print("   au repos, a 2,1 s : onglet %s, saisie %s, colonne %s, debordement %s" % (
        [o.alpha for o in tab1], [o.alpha for o in input1], [o.alpha for o in buttons1], [o.alpha for o in overhang]))
    assert all(o.alpha == 0 for o in tab1 + input1 + buttons1 + overhang) and overhang
    assert g.ChatFrame1TabGlow.alpha == 0.7 and g.ChatFrame1Tab.alpha == 0.4 and g.ChatFrame1EditBox.alpha == 0.35
    assert all(not b.shown and b.alpha == 0 for b in fl), "les fleches restent cachees"
    # The active edit box stays fully visible, even when idle
    lua.execute("ACTIVE_CHAT_EDIT_BOX = ChatFrame1EditBox")
    engine(0.01)
    assert all(o.alpha == 1 for o in input1) and all(o.alpha == 0 for o in tab1)
    lua.execute("ACTIVE_CHAT_EDIT_BOX = nil")
    engine(0.01)
    assert all(o.alpha == 0 for o in input1)
    # A docked window that is not selected is hidden; its tab still follows
    lua.execute("ChatFrame2:Hide(); FCF_FadeInChatFrame(ChatFrame2)")
    engine(0.2)
    assert g.ChatFrame2TabLeft.alpha == 1 and g.ChatFrame1TabLeft.alpha == 0
    lua.execute("FCF_FadeOutChatFrame(ChatFrame2); ChatFrame2:Show()")
    engine(2.1)
    assert g.ChatFrame2TabLeft.alpha == 0
    # Background: the saved opacity is set to 0 once, on ForeverUI's
    # ADDON_LOADED; what the user sets afterwards is kept
    watcher = C.watcher
    lua.execute("ForeverUIDB = ForeverUIDB or {}; ForeverUIDB.chatIdleBackground = nil")
    watcher.scripts.OnEvent(watcher, "ADDON_LOADED", "Blizzard_TimeManager")
    assert abs(g.OPACITIES[1] - 40 / 255) < 1e-9 and watcher.events["ADDON_LOADED"]
    watcher.scripts.OnEvent(watcher, "ADDON_LOADED", "ForeverUI")
    print("   fond retenu : %s, fait %s" % ([round(v, 3) for v in g.OPACITIES.values()], g.ForeverUIDB.chatIdleBackground))
    assert all(v == 0 for v in g.OPACITIES.values()) and g.ForeverUIDB.chatIdleBackground
    assert not watcher.events["ADDON_LOADED"]
