    lua.execute("ChatFrame1.isDocked = true; ChatFrame2.isDocked = true; FCF_FadeOutChatFrame(ChatFrame1); FCF_FadeOutChatFrame(ChatFrame2)")
    engine(2.5)
    background1 = g.ChatFrame1Background
    lua.execute("ChatFrame1.oldAlpha = 0; ChatFrame1Background:SetAlpha(0); ChatFrame1TopLeftTexture:SetAlpha(0)")
    linings = [pr[2] for pr in d1.doubles.values()]
    assert len(linings) == 3 and not any(t.shown for t in linings)
    assert linings[0].texture == background1.texture and linings[0].layer == "BACKGROUND" and lua.eval("rawequal")(linings[0].allPoints, background1)
    assert list(linings[1].texcoord8.values()) == [0, 1, 0, 0, 1, 1, 1, 0], list(linings[1].texcoord8.values())
    lua.execute("FADED = {}")
    c1.mouse = True
    engine(0.1)
    assert not d1.isLit
    engine(0.15)
