    print("   survol : allume %s, dock %s, onglets %s / %s, doublure du fond %.2f" % (
        d1.isLit, d2.isLit, g.ChatFrame1TabLeft.alpha, g.ChatFrame2TabLeft.alpha, linings[0].alpha))
    assert d1.isLit and d2.isLit and g.ChatFrame1TabLeft.alpha == 1 and g.ChatFrame2TabLeft.alpha == 1
    assert list(g.FADED.values()) == [], "on ne demande rien au client"
    assert linings[0].shown and abs(linings[0].alpha - 0.25) < 1e-9 and linings[0].vertex[1] == 0
    # The client lights up in turn: the lining fades; halfway,
    # it makes up the difference (1 - 0.75 / 0.9)
    lua.execute("ChatFrame1Background:SetAlpha(0.25)")
    engine(0.01)
    assert not linings[0].shown
    lua.execute("ChatFrame1Background:SetAlpha(0.1)")
    engine(0.01)
    assert abs(linings[0].alpha - (1 - 0.75 / 0.9)) < 1e-9
    lua.execute("ChatFrame1Background:SetAlpha(0)")
    # Outside: still lit at 0.9 s, off at 1 s, gone in 2 s
