    o1, o2 = g.ChatFrame1Tab, g.ChatFrame2Tab
    assert [anchor(g.ChatFrame1TabLeft, i) for i in range(len(pts(g.ChatFrame1TabLeft)))] == [("BOTTOMLEFT", "ChatFrame1Tab", "BOTTOMLEFT", -2, 0)]
    assert [anchor(g.ChatFrame1TabRight, i) for i in range(len(pts(g.ChatFrame1TabRight)))] == [("BOTTOMRIGHT", "ChatFrame1Tab", "BOTTOMRIGHT", 2, 0)]
    assert [anchor(g.ChatFrame1TabMiddle, i) for i in range(len(pts(g.ChatFrame1TabMiddle)))] == [
        ("LEFT", "ChatFrame1TabLeft", "RIGHT", 0, 0), ("RIGHT", "ChatFrame1TabRight", "LEFT", 0, 0)]
    assert [anchor(g.ChatFrame1TabText, i) for i in range(len(pts(g.ChatFrame1TabText)))] == [("CENTER", "ChatFrame1Tab", "CENTER", 0, -5)]
    print("   onglets : General %s (texte %s), Combat Log %s (texte %s)" % (o1.width, g.ChatFrame1TabText.width, o2.width, g.ChatFrame2TabText.width))
    assert (o1.width, g.ChatFrame1TabText.width) == (42 + 20, 42) and (o2.width, g.ChatFrame2TabText.width) == (60 + 20, 60)
    dk = g.GENERAL_CHAT_DOCK
    assert [anchor(dk, i) for i in range(len(pts(dk)))] == [
        ("BOTTOMLEFT", "ChatFrame1Background", "TOPLEFT", 0, 0), ("BOTTOMRIGHT", "ChatFrame1Background", "TOPRIGHT", 0, 0)]
    # Checks the Camelot dock layout: tabs 1 apart, overflow button on the right
    def camelot_dock():
        assert [anchor(o1, i) for i in range(len(pts(o1)))] == [("BOTTOMLEFT", "GeneralDockManager", "BOTTOMLEFT", 0, 0)], pts(o1)
        assert [anchor(o2, i) for i in range(len(pts(o2)))] == [("LEFT", "ChatFrame1Tab", "RIGHT", 1, 0)]
        assert anchor(dk.overflowButton) == ("BOTTOMRIGHT", "GeneralDockManager", "BOTTOMRIGHT", 0, 0)
    camelot_dock()
    assert anchor(dk.scrollFrame) == ("BOTTOMRIGHT", "GeneralDockManager", "BOTTOMRIGHT", 0, 0)
    # The client re-lays out the dock (3.3.5: tabs touching, text + 32):
