    assert (o1.width, g.ChatFrame1TabText.width) == (32, 12)
    lua.execute("ChatFrame1TabText:SetText('General'); PanelTemplates_TabResize(ChatFrame1Tab, 0)")
    assert o1.width == 62
    # Another game tab keeps the client's size
