    at.scripts.OnUpdate(at)
    rel = g.ForeverUIDB.chatRecord
    print("   releve : fenetre %s, %s objets texte, %s derniers messages" % (rel.window, len(list(rel.texts.values())), len(list(rel.latest.values()))))
    assert rel.window == "ChatFrame1" and not at.shown
    t0 = [t for t in rel.texts.values()][-1]
    assert t0.text == "[Guild] Papota: bonjour" and t0.measure == len("[Guild] Papota: bonjour") * 6 and t0.font

    # Alt-drag selection: two messages laid out as the engine does it
    # (one font string per message, wrapped to the width); the first carries
    # the EasyCopy timestamp (a link) and wraps to three lines at 120:
    # "[10:00:00] [Guild]" / "Papota: bonjour a" / "tous"
    print("\nselection du chat :")
    lua.execute("""
        local function message(text, top, rows)
            local m = ChatFrame1:CreateFontString(nil, "ARTWORK")
            m:SetText(text)
            m:SetWidth(120)
            m._left, m._top, m._bottom, m._right = 40, top, top - 12 * rows, 160
            return m
        end
        MESSAGE1 = message("|Hezc:x|h[10:00:00] |h[Guild] Papota: bonjour a tous", 200, 3)
        MESSAGE2 = message("Deuxieme message", 164, 1)
    """)
    Sel = C.selection
    cap = d1.catcher
    sel_watcher = C.selectionWatcher
    # Runs one frame of the selection watcher
    def watch():
        sel_watcher.scripts.OnUpdate(sel_watcher, 0.01)
    watch()
    assert not cap.mouseEnabled, "sans Alt, le chat laisse passer la souris"
    lua.execute("BINDINGS.alt = true")
    watch()
    assert cap.mouseEnabled
    c = lua.eval("ForeverUI.Chat.layout(MESSAGE1)")
    print("   lignes du premier message : debuts %s, hauteur %s" % (list(c.starts.values()), c.lineHeight))
    assert list(c.starts.values()) == [1, 20, 38] and c.lineHeight == 12
    # Press before the G of [Guild] (line 1, x 72), drag to the middle of
    # line 2 (x 42, before the space after "Papota:")
    lua.execute("MOUSE_X, MOUSE_Y = 40 + 72, 194")
    cap.scripts.OnMouseDown(cap, "LeftButton")
    lua.execute("BINDINGS.alt = false; MOUSE_X, MOUSE_Y = 40 + 42, 182")
    watch()
    assert cap.mouseEnabled, "le glisser garde la souris meme Alt relache"
    assert lua.eval("ForeverUI.Chat.selectionText()") == "Guild] Papota:"
    hls = [t for t in d1.highlights.values() if t.shown]
    print("   surlignage : %s" % [(anchor(t)[3], anchor(t)[4], t.width, t.height, t.layer) for t in hls])
    assert [(anchor(t)[3], anchor(t)[4], t.width, t.height) for t in hls] == [(72, 0, 42, 12), (0, -12, 42, 12)]
    assert all(t.layer == "BORDER" for t in hls)
    # Down below the last message: the end of the first, then the second
    lua.execute("MOUSE_X, MOUSE_Y = 300, 100")
    watch()
    cap.scripts.OnMouseUp(cap, "LeftButton")
    bx = Sel.box
    print("   copie : %r, saisie %s" % (bx.text, bx.focused))
    # On release, the keyboard stays with the game: the edit box holds the text
    # without taking focus
    assert bx.text == "Guild] Papota: bonjour a tous\nDeuxieme message" and not bx.focused
    watch()
    assert not cap.mouseEnabled and Sel.text and any(t.shown for t in d1.highlights.values())
    # Ctrl pressed: the edit box takes the keyboard, text highlighted, read-only;
