        assert abs(b.x - ex) < 1e-6 and abs(b.y - ey) < 1e-6, (i, b.x, ex, b.y, ey)
        p = pts(b)[-1]
        assert p[0] == "CENTER" and req(p[1], c) and p[2:] == ["BOTTOMLEFT", int(ex + 0.5), int(ey + 0.5)]
