    # text WITHIN the width set on it (hence 3.3.5's TradeSkillFrameDummyString); the fake
    # simulates that on the row names. The name is measured on its own, never bounded.
    lua.execute("""
        local function boundedWidth(self)
            local l = string.len(self.text or "") * 6
            if self.width and self.width > 0 and self.width < l then return self.width end
            return l
        end
        TRADE_SKILL.linked = nil
        TRADE_SKILL.recipes = { { "Parts", "header", 0, 1 }, { "Linen", "optimal", 0, nil, nil, "i", nil, 1, 1, reagents = {} } }
        TradeSkillFrame_Update()
        for _, b in ipairs(ForeverUI.Professions.skin.recipes) do b.name.GetStringWidth = boundedWidth end
        TRADE_SKILL.recipes[2][1] = "Rough Blasting Powder"
        TradeSkillFrame_Update()
    """)
