    # THE ENGINE'S VALID CHOICES, computed here independently of the addon from the client
    # data (BarberShopData.lua): a slot is valid if its digit divided by the weight
    # (1, or 2 for a death knight) is odd
    def choice_string(race, sex, section, var):
        return g.ForeverUI.AppearanceChoices[race][sex][section][var] or ""
    def allowed(text, weight):
        return [c for c, x in enumerate(text) if x != "." and (int(x) // weight) % 2 == 1]
    def valid(race, sex, weight, hairStyle, facialHair, color, face):
        d = g.ForeverUI.AppearanceChoices[race][sex]
        n3, n2 = d[3]["n"], d[2]["n"]
        v = {1: [x for x in range(n3) if allowed(choice_string(race, sex, 3, x), weight)],
             2: allowed(choice_string(race, sex, 3, hairStyle), weight)}
        if facialHair < n2 and color < len(choice_string(race, sex, 2, facialHair)):
            v[3] = [x for x in range(n2) if allowed(choice_string(race, sex, 2, x), weight)]
        else:
            v[3] = list(range(d["facialHairs"]))
        skinColor = set(allowed(choice_string(race, sex, 0, 0), weight))
        skinColor &= set(allowed(choice_string(race, sex, 1, face), weight))
        skinColor &= set(allowed(choice_string(race, sex, 4, 0), weight))
        v[4] = sorted(skinColor)
        return v
    def set_valid(v):
        lua.execute("BARBER.valid = {}")
        for i, l in v.items():
            lua.execute("BARBER.valid[%d] = { %s }" % (i, ", ".join(str(x) for x in l)))
    Tplc = g.ForeverUI.Templates
